globalThis.ETERNA_LIBRARY_CONTENT={"release_id":"eterna-library-2026.09-v1","coverage_complete":false,"human_teacher_reviewed":false,"lessons":[{"id":"i-count","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Contar objetos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Contar objetos","contar","conteo","aprender a contar"],"explanation":"Contar sirve para saber cuántas cosas hay. Señala un objeto cada vez y di los números en orden. El último número que dices indica cuántos objetos has contado.","simpler":"Vamos despacito: toca una pieza, di «uno»; toca otra, di «dos». No vuelvas a contar la misma pieza.","example":"Con un adulto, coloca tres piezas grandes: cuenta una, dos y tres. Hay tres piezas, aunque las separes un poco.","why":"El número describe la cantidad, no el espacio que ocupan los objetos. Moverlos sin añadir ni quitar conserva la cantidad.","misconception":"Separar los objetos no cambia cuántos hay.","hints":["Toca cada objeto una sola vez y escucha el último número.","Vamos despacito: toca una pieza, di «uno»; toca otra, di «dos». No vuelvas a contar la misma pieza.","Con un adulto, coloca tres piezas grandes: cuenta una, dos y tres. Hay tres piezas, aunque las separes un poco."],"quiz":[{"id":"i-count:q0","question":"Si cuentas uno, dos y tres, ¿cuántas piezas hay?","options":["Dos","Tres","Cuatro"],"answer":"B","hint":"Toca cada objeto una sola vez y escucha el último número.","level":1},{"id":"i-count:q1","question":"¿Qué haces al contar?","options":["Señalar cada pieza una vez","Contar siempre la misma","Saltar piezas"],"answer":"A","hint":"Toca cada objeto una sola vez y escucha el último número.","level":2},{"id":"i-count:q2","question":"Si separas las tres piezas sin quitar ninguna, ¿cuántas quedan?","options":["Una","Cuatro","Tres"],"answer":"C","hint":"Toca cada objeto una sola vez y escucha el último número.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-shapes","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Formas geométricas","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Formas geométricas","formas","circulo","triangulo","cuadrado"],"explanation":"Podemos reconocer formas por su borde. Un círculo tiene un borde curvo. Un triángulo tiene tres lados rectos. Un cuadrado tiene cuatro lados iguales y cuatro esquinas como las de una hoja.","simpler":"Un círculo es redondito. Un triángulo tiene tres lados. Un cuadrado tiene cuatro lados iguales.","example":"Con un adulto, busca una tapa redonda y una hoja cuadrada. Recorre sus bordes con el dedo sin usar objetos cortantes.","why":"Los lados y las esquinas nos ayudan a clasificar las figuras aunque tengan otro color o estén giradas.","misconception":"Girar una figura no hace que deje de ser la misma forma.","hints":["Mira el borde y cuenta los lados rectos.","Un círculo es redondito. Un triángulo tiene tres lados. Un cuadrado tiene cuatro lados iguales.","Con un adulto, busca una tapa redonda y una hoja cuadrada. Recorre sus bordes con el dedo sin usar objetos cortantes."],"quiz":[{"id":"i-shapes:q0","question":"¿Qué forma tiene tres lados?","options":["Círculo","Cuadrado","Triángulo"],"answer":"C","hint":"Mira el borde y cuenta los lados rectos.","level":1},{"id":"i-shapes:q1","question":"¿Cuál tiene un borde curvo?","options":["Círculo","Triángulo","Cuadrado"],"answer":"A","hint":"Mira el borde y cuenta los lados rectos.","level":2},{"id":"i-shapes:q2","question":"¿Cuántos lados tiene un cuadrado?","options":["Tres","Cuatro","Cinco"],"answer":"B","hint":"Mira el borde y cuenta los lados rectos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-patterns","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Series y patrones","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Series y patrones","series","patrones","series logicas"],"explanation":"Un patrón repite una regla. Antes de continuar una serie, busca qué grupo se repite. Puede ser una secuencia de colores, formas o sonidos.","simpler":"Busca el trocito que se repite: rojo, azul; rojo, azul.","example":"Con piezas grandes, forma círculo, cuadrado, círculo, cuadrado. El grupo que se repite es círculo-cuadrado.","why":"Reconocer la regla permite anticipar lo que viene después sin memorizar una lista entera.","misconception":"Una serie no se continúa eligiendo al azar.","hints":["Repite en voz baja el grupo más pequeño de la serie.","Busca el trocito que se repite: rojo, azul; rojo, azul.","Con piezas grandes, forma círculo, cuadrado, círculo, cuadrado. El grupo que se repite es círculo-cuadrado."],"quiz":[{"id":"i-patterns:q0","question":"En rojo, azul, rojo, azul, ¿qué sigue?","options":["Rojo","Verde","Azul"],"answer":"A","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":1},{"id":"i-patterns:q1","question":"En palma, pie, palma, pie, ¿qué sigue?","options":["Pie","Palma","Silencio"],"answer":"B","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":2},{"id":"i-patterns:q2","question":"¿Qué conviene buscar primero?","options":["El color favorito","La pieza más grande","El grupo que se repite"],"answer":"C","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-position","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Dentro y fuera","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Dentro y fuera","dentro y fuera","posiciones","ubicacion"],"explanation":"Dentro y fuera indican dónde está algo respecto a un límite. Una pieza está dentro si está en el espacio de la caja; está fuera si no está en ese espacio.","simpler":"Mira la caja: lo que está en su interior está dentro. Lo que está al lado, fuera.","example":"Coloca una pieza grande dentro de una caja y otra junto a la caja, con un adulto. Describe dónde está cada una.","why":"Estas palabras necesitan una referencia: dentro de la caja, fuera del aro o dentro de la habitación.","misconception":"La misma pieza puede cambiar de posición sin cambiar de tamaño.","hints":["Observa el borde de la caja.","Mira la caja: lo que está en su interior está dentro. Lo que está al lado, fuera.","Coloca una pieza grande dentro de una caja y otra junto a la caja, con un adulto. Describe dónde está cada una."],"quiz":[{"id":"i-position:q0","question":"Una pieza en el interior de la caja está…","options":["Lejos","Dentro","Fuera"],"answer":"B","hint":"Observa el borde de la caja.","level":1},{"id":"i-position:q1","question":"Una pieza al lado de la caja está…","options":["Fuera","Dentro","Debajo siempre"],"answer":"A","hint":"Observa el borde de la caja.","level":2},{"id":"i-position:q2","question":"Para decir dentro o fuera, ¿qué debemos mirar?","options":["Solo el color","Solo el tamaño","El límite del recipiente"],"answer":"C","hint":"Observa el borde de la caja.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-emotions","stage":"infantil","subject":"Crecimiento en armonía","title":"Reconocer emociones","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Reconocer emociones","emociones","sentimientos"],"explanation":"Las emociones nos ayudan a reconocer cómo vivimos una situación. Podemos sentir alegría, tristeza, enfado o miedo. Todas pueden aparecer; lo importante es expresarlas sin hacernos daño ni dañar a otros.","simpler":"Puedes decir «estoy triste» o «estoy enfadado». Un adulto de confianza puede escucharte y ayudarte.","example":"Si una torre se cae y te enfadas, puedes parar, respirar despacio y decirle al adulto que necesitas ayuda para reconstruirla.","why":"Nombrar una emoción permite comunicar una necesidad; no es una etiqueta permanente sobre quién eres.","misconception":"No hay que fingir estar contento todo el tiempo.","hints":["Pon nombre a lo que sientes y busca apoyo cercano.","Puedes decir «estoy triste» o «estoy enfadado». Un adulto de confianza puede escucharte y ayudarte.","Si una torre se cae y te enfadas, puedes parar, respirar despacio y decirle al adulto que necesitas ayuda para reconstruirla."],"quiz":[{"id":"i-emotions:q0","question":"¿A quién puedes contar que estás triste?","options":["A un adulto de confianza","A nadie nunca","Solo a la pantalla"],"answer":"A","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":1},{"id":"i-emotions:q1","question":"Si te enfadas, ¿qué puedes hacer?","options":["Pegar","Romperlo todo","Parar y pedir ayuda"],"answer":"C","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":2},{"id":"i-emotions:q2","question":"¿Sentir tristeza significa portarse mal?","options":["Siempre","No","Solo por la noche"],"answer":"B","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-turns","stage":"infantil","subject":"Crecimiento en armonía","title":"Respetar los turnos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Respetar los turnos","turnos","esperar el turno"],"explanation":"Compartir un juego significa dar espacio a otras personas. Respetar un turno es esperar mientras participa otra persona y actuar cuando te corresponde. Puedes pedir ayuda para organizarlo.","simpler":"Ahora juega una persona y después otra. Esperar no significa que te hayan olvidado.","example":"En un juego con una pelota, Ana la pasa a Luis y después Luis a Ana. Ambos participan.","why":"Las reglas compartidas hacen el juego más previsible y ayudan a resolver desacuerdos sin daño.","misconception":"Esperar un turno no elimina tu derecho a participar.","hints":["Piensa en qué permite jugar también a la otra persona.","Ahora juega una persona y después otra. Esperar no significa que te hayan olvidado.","En un juego con una pelota, Ana la pasa a Luis y después Luis a Ana. Ambos participan."],"quiz":[{"id":"i-turns:q0","question":"¿Qué haces mientras le toca a otra persona?","options":["Quitarle el material","Esperar tu turno","Gritar para empezar"],"answer":"B","hint":"Piensa en qué permite jugar también a la otra persona.","level":1},{"id":"i-turns:q1","question":"¿Qué ayuda si no sabemos a quién le toca?","options":["Pedir ayuda para acordarlo","Abandonar siempre","Empujar"],"answer":"A","hint":"Piensa en qué permite jugar también a la otra persona.","level":2},{"id":"i-turns:q2","question":"¿Para qué sirven los turnos?","options":["Para que juegue solo uno","Para decidir quién vale más","Para que todos puedan participar"],"answer":"C","hint":"Piensa en qué permite jugar también a la otra persona.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-sequence","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Antes y después","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Antes y después","antes y despues","secuencias temporales"],"explanation":"Antes y después nos ayudan a ordenar lo que ocurre. Una acción puede ir antes de otra. Podemos contar una historia siguiendo ese orden.","simpler":"Primero ocurre una cosa y luego otra. Mira cuál sucede antes.","example":"Antes de salir, te pones los zapatos. Después sales con el adulto que te acompaña.","why":"Ordenar los hechos ayuda a explicar una rutina y a anticipar qué necesitamos hacer.","misconception":"Antes y después dependen del acontecimiento que tomamos como referencia.","hints":["Busca qué pasó primero.","Primero ocurre una cosa y luego otra. Mira cuál sucede antes.","Antes de salir, te pones los zapatos. Después sales con el adulto que te acompaña."],"quiz":[{"id":"i-sequence:q0","question":"Si primero te pones los zapatos y luego sales, ¿qué va antes?","options":["Ponerte los zapatos","Salir","Las dos a la vez siempre"],"answer":"A","hint":"Busca qué pasó primero.","level":1},{"id":"i-sequence:q1","question":"¿Qué palabra indica que algo ocurre más tarde?","options":["Antes","Dentro","Después"],"answer":"C","hint":"Busca qué pasó primero.","level":2},{"id":"i-sequence:q2","question":"Para contar una historia, ayuda…","options":["Mezclar siempre todo","Ordenar lo que ocurrió","Cambiar todos los personajes"],"answer":"B","hint":"Busca qué pasó primero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-rhymes","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Rimas","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Rimas","rimas","rimar"],"explanation":"Dos palabras riman cuando comparten sonidos al final de una forma reconocible. Podemos escuchar sus finales y jugar a compararlos.","simpler":"Escucha el final: gato y pato suenan parecido al terminar.","example":"Di despacio «gato» y «pato». Comparten el final «ato». Después compáralas con «sol».","why":"Al fijarte en los sonidos entrenas la atención al lenguaje; no hace falta saber leer para jugar con rimas.","misconception":"Rimar depende de los sonidos, no del significado.","hints":["Repite despacio la última parte de cada palabra.","Escucha el final: gato y pato suenan parecido al terminar.","Di despacio «gato» y «pato». Comparten el final «ato». Después compáralas con «sol»."],"quiz":[{"id":"i-rhymes:q0","question":"¿Qué palabra rima con gato?","options":["Mesa","Pato","Sol"],"answer":"B","hint":"Repite despacio la última parte de cada palabra.","level":1},{"id":"i-rhymes:q1","question":"¿Qué escuchamos para buscar una rima?","options":["El final de las palabras","El color de las letras","El tamaño del papel"],"answer":"A","hint":"Repite despacio la última parte de cada palabra.","level":2},{"id":"i-rhymes:q2","question":"¿Qué pareja rima?","options":["Pan y nube","Flor y mesa","Luna y cuna"],"answer":"C","hint":"Repite despacio la última parte de cada palabra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-senses","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Los sentidos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Los sentidos","sentidos","cinco sentidos"],"explanation":"Usamos los sentidos para obtener información del entorno. La vista permite ver, el oído escuchar, el olfato oler, el gusto saborear y el tacto notar, por ejemplo, una textura. No necesitamos tocar o probar algo para conocerlo si puede ser peligroso.","simpler":"Los ojos ven y los oídos escuchan. Las manos pueden notar si una tela es suave.","example":"Con un adulto, mira un pañuelo, escucha unas palmas y toca una tela segura. Nunca pruebes ni huelas sustancias desconocidas.","why":"Cada sentido aporta información distinta; podemos combinarlos de forma segura para explorar.","misconception":"La curiosidad no obliga a tocar ni probar objetos desconocidos.","hints":["Relaciona la información con el sentido que la detecta.","Los ojos ven y los oídos escuchan. Las manos pueden notar si una tela es suave.","Con un adulto, mira un pañuelo, escucha unas palmas y toca una tela segura. Nunca pruebes ni huelas sustancias desconocidas."],"quiz":[{"id":"i-senses:q0","question":"¿Qué usamos principalmente para escuchar?","options":["Ojos","Lengua","Oídos"],"answer":"C","hint":"Relaciona la información con el sentido que la detecta.","level":1},{"id":"i-senses:q1","question":"¿Qué sentido permite notar una tela suave?","options":["Tacto","Vista únicamente","Olfato"],"answer":"A","hint":"Relaciona la información con el sentido que la detecta.","level":2},{"id":"i-senses:q2","question":"¿Debemos probar una sustancia desconocida?","options":["Siempre","No","Solo si tiene buen color"],"answer":"B","hint":"Relaciona la información con el sentido que la detecta.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-syllables","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Sílabas","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Sílabas","silabas","separar palabras"],"explanation":"Las palabras se pueden pronunciar en partes llamadas sílabas. Podemos marcar cada parte con una palmada suave mientras hablamos.","simpler":"Di «ca-sa»: oyes dos partes. Da una palmada por cada parte.","example":"Pronuncia «ma-ri-po-sa» despacio: son cuatro sílabas. No confundas las sílabas con el número de letras.","why":"Escuchar partes dentro de las palabras prepara para relacionar el habla con la lectura y la escritura.","misconception":"Una sílaba puede contener más de una letra.","hints":["Pronuncia la palabra, sin añadir ni quitar sonidos.","Di «ca-sa»: oyes dos partes. Da una palmada por cada parte.","Pronuncia «ma-ri-po-sa» despacio: son cuatro sílabas. No confundas las sílabas con el número de letras."],"quiz":[{"id":"i-syllables:q0","question":"¿Cuántas sílabas tiene casa?","options":["Una","Dos","Tres"],"answer":"B","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":1},{"id":"i-syllables:q1","question":"¿Cómo se separa mariposa?","options":["Ma-ri-po-sa","Mar-ip-osa","Mari-po-sa siempre"],"answer":"A","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":2},{"id":"i-syllables:q2","question":"Una palmada por cada parte nos ayuda a contar…","options":["Los colores","Las letras exactas","Las sílabas"],"answer":"C","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-compare","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Más y menos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Más y menos","mas y menos","comparar cantidades"],"explanation":"Para comparar dos grupos puedes emparejar un objeto de uno con otro del segundo. Si sobran objetos en un grupo, ese grupo tiene más. Si no sobra ninguno, tienen la misma cantidad.","simpler":"Haz parejas entre los dos grupos. Mira en cuál quedan piezas sin pareja.","example":"Coloca tres piezas grandes y, enfrente, dos. Al emparejarlas sobra una en el grupo de tres: tiene más.","why":"La correspondencia uno a uno permite comparar cantidades sin depender del tamaño de los objetos.","misconception":"Un grupo más extendido no tiene necesariamente más objetos.","hints":["Empareja un objeto de cada grupo.","Haz parejas entre los dos grupos. Mira en cuál quedan piezas sin pareja.","Coloca tres piezas grandes y, enfrente, dos. Al emparejarlas sobra una en el grupo de tres: tiene más."],"quiz":[{"id":"i-compare:q0","question":"Entre tres piezas y dos piezas, ¿dónde hay más?","options":["En el grupo de tres","En el de dos","Siempre lo mismo"],"answer":"A","hint":"Empareja un objeto de cada grupo.","level":1},{"id":"i-compare:q1","question":"Si todos los objetos tienen pareja y no sobra ninguno, hay…","options":["Más en el primero","Menos en el segundo","La misma cantidad"],"answer":"C","hint":"Empareja un objeto de cada grupo.","level":2},{"id":"i-compare:q2","question":"Para comparar sin contar podemos…","options":["Mirar solo la separación","Emparejar objetos","Cambiar los colores"],"answer":"B","hint":"Empareja un objeto de cada grupo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-living","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Seres vivos","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Seres vivos","seres vivos","plantas y animales"],"explanation":"Los seres vivos realizan funciones vitales, como nutrirse y relacionarse con el entorno; las poblaciones continúan mediante la reproducción. Las plantas y los animales son seres vivos. No todo lo que se mueve está vivo.","simpler":"Una planta necesita agua y condiciones adecuadas para vivir. Un coche se mueve, pero no está vivo.","example":"Observa una planta con un adulto durante varios días. Puedes ver cómo crece, sin arrancar sus hojas ni molestar a animales.","why":"Las funciones vitales distinguen a los organismos de los objetos, aunque algunos objetos se muevan o consuman energía.","misconception":"Moverse no basta para decir que algo es un ser vivo.","hints":["Compara una planta con un objeto construido.","Una planta necesita agua y condiciones adecuadas para vivir. Un coche se mueve, pero no está vivo.","Observa una planta con un adulto durante varios días. Puedes ver cómo crece, sin arrancar sus hojas ni molestar a animales."],"quiz":[{"id":"i-living:q0","question":"¿Cuál es un ser vivo?","options":["Una bicicleta","Una planta","Una piedra"],"answer":"B","hint":"Compara una planta con un objeto construido.","level":1},{"id":"i-living:q1","question":"¿Todo lo que se mueve está vivo?","options":["No","Sí","Solo si va rápido"],"answer":"A","hint":"Compara una planta con un objeto construido.","level":2},{"id":"i-living:q2","question":"¿Cómo podemos observar una planta?","options":["Arrancándola siempre","Sin cuidarla","Mirándola y cuidándola con un adulto"],"answer":"C","hint":"Compara una planta con un objeto construido.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-add","stage":"primaria","subject":"Matemáticas","title":"La suma","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La suma","sumas","sumar","adicion"],"explanation":"Sumar reúne cantidades o añade una cantidad a otra. El resultado se llama suma. Puedes comprobar una suma cambiando el orden de sus sumandos: el resultado se conserva.","simpler":"Junta un grupo con otro y cuenta cuántos elementos hay en total.","example":"Si tienes 3 lápices y recibes 2, ahora tienes 5: 3 + 2 = 5.","why":"La suma de cantidades cuenta todos los elementos sin contarlos dos veces.","misconception":"Sumar cero no cambia una cantidad.","hints":["Empieza por la primera cantidad y añade la segunda.","Junta un grupo con otro y cuenta cuántos elementos hay en total.","Si tienes 3 lápices y recibes 2, ahora tienes 5: 3 + 2 = 5."],"quiz":[{"id":"p-add:q0","question":"¿Cuánto es 4 + 3?","options":["6","7","8"],"answer":"B","hint":"Empieza por la primera cantidad y añade la segunda.","level":1},{"id":"p-add:q1","question":"¿Cómo se llaman los números que sumamos?","options":["Sumandos","Divisores","Denominadores"],"answer":"A","hint":"Empieza por la primera cantidad y añade la segunda.","level":2},{"id":"p-add:q2","question":"¿Cuánto es 8 + 0?","options":["0","1","8"],"answer":"C","hint":"Empieza por la primera cantidad y añade la segunda.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-sub","stage":"primaria","subject":"Matemáticas","title":"La resta","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La resta","restas","restar","sustraccion"],"explanation":"Restar permite quitar una cantidad o calcular cuánto separa dos cantidades. Puedes comprobar una resta sumando el resultado y la cantidad que quitaste.","simpler":"Imagina lo que tienes, quita una parte y mira cuánto queda.","example":"De 9 cromos entregas 4: quedan 5. La comprobación es 5 + 4 = 9.","why":"La resta y la suma se relacionan: una permite deshacer la otra en estas operaciones.","misconception":"Cambiar el orden de una resta suele cambiar el resultado.","hints":["Piensa qué cantidad debes añadir al número menor para llegar al mayor.","Imagina lo que tienes, quita una parte y mira cuánto queda.","De 9 cromos entregas 4: quedan 5. La comprobación es 5 + 4 = 9."],"quiz":[{"id":"p-sub:q0","question":"¿Cuánto es 9 − 4?","options":["5","4","13"],"answer":"A","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":1},{"id":"p-sub:q1","question":"¿Cómo compruebas 12 − 5 = 7?","options":["12 + 7","5 − 7","7 + 5 = 12"],"answer":"C","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":2},{"id":"p-sub:q2","question":"¿Cuánto es 6 − 0?","options":["0","6","1"],"answer":"B","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-mul","stage":"primaria","subject":"Matemáticas","title":"La multiplicación","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La multiplicación","multiplicaciones","multiplicar","tablas de multiplicar"],"explanation":"La multiplicación de números naturales puede representar grupos con la misma cantidad. Primero identifica cuántos grupos hay y cuántos elementos tiene cada uno. El resultado se llama producto.","simpler":"Cuenta grupos iguales en vez de ir objeto por objeto.","example":"Cuatro bolsas con tres canicas cada una contienen 4 × 3 = 12 canicas.","why":"La multiplicación abrevia una suma repetida cuando todos los grupos son iguales.","misconception":"Sumar el número de grupos y el tamaño del grupo no da el total.","hints":["Puedes sumar varias veces la misma cantidad.","Cuenta grupos iguales en vez de ir objeto por objeto.","Cuatro bolsas con tres canicas cada una contienen 4 × 3 = 12 canicas."],"quiz":[{"id":"p-mul:q0","question":"¿Cuánto es 6 × 4?","options":["10","24","20"],"answer":"B","hint":"Puedes sumar varias veces la misma cantidad.","level":1},{"id":"p-mul:q1","question":"Tres cajas con 5 piezas cada una tienen…","options":["15 piezas","8 piezas","2 piezas"],"answer":"A","hint":"Puedes sumar varias veces la misma cantidad.","level":2},{"id":"p-mul:q2","question":"¿Cuánto es 9 × 1?","options":["1","0","9"],"answer":"C","hint":"Puedes sumar varias veces la misma cantidad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-div","stage":"primaria","subject":"Matemáticas","title":"La división","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La división","divisiones","dividir","division exacta"],"explanation":"Dividir puede servir para repartir en partes iguales o para averiguar cuántos grupos de un tamaño caben. En una división exacta, divisor por cociente da el dividendo. No se divide entre cero.","simpler":"Reparte la misma cantidad a cada grupo, sin favorecer a ninguno.","example":"Reparte 18 fichas entre 3 grupos: cada uno recibe 6. Comprueba: 3 × 6 = 18.","why":"El reparto y la agrupación son dos interpretaciones de la misma relación entre multiplicación y división.","misconception":"Dividir no siempre es simplemente hacer un número menor: depende del divisor.","hints":["Busca un número que, multiplicado por el divisor, produzca el dividendo.","Reparte la misma cantidad a cada grupo, sin favorecer a ninguno.","Reparte 18 fichas entre 3 grupos: cada uno recibe 6. Comprueba: 3 × 6 = 18."],"quiz":[{"id":"p-div:q0","question":"¿Cuánto es 18 ÷ 3?","options":["15","9","6"],"answer":"C","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":1},{"id":"p-div:q1","question":"¿Qué comprueba 24 ÷ 4 = 6?","options":["4 × 6 = 24","24 + 6 = 4","4 − 6 = 24"],"answer":"A","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":2},{"id":"p-div:q2","question":"¿Se puede dividir entre cero?","options":["Sí, siempre","No está definido","Da siempre uno"],"answer":"B","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-place","stage":"primaria","subject":"Matemáticas","title":"Valor posicional","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Valor posicional","valor posicional","unidades decenas y centenas"],"explanation":"En nuestro sistema decimal, el valor de una cifra depende de su posición. Diez unidades forman una decena y diez decenas una centena. El cero puede indicar que no hay unidades de un orden.","simpler":"Una cifra cambia de valor cuando cambia de sitio. En 24, el 2 vale dos decenas.","example":"En 305 hay 3 centenas, 0 decenas y 5 unidades: 300 + 0 + 5.","why":"Agrupar de diez en diez permite escribir muchas cantidades con solo diez cifras.","misconception":"La cifra y el valor de esa cifra no son lo mismo.","hints":["Lee el nombre de cada posición desde la derecha.","Una cifra cambia de valor cuando cambia de sitio. En 24, el 2 vale dos decenas.","En 305 hay 3 centenas, 0 decenas y 5 unidades: 300 + 0 + 5."],"quiz":[{"id":"p-place:q0","question":"En 472, el 7 representa…","options":["7 unidades","70 unidades","700 unidades"],"answer":"B","hint":"Lee el nombre de cada posición desde la derecha.","level":1},{"id":"p-place:q1","question":"¿Cuántas unidades hay en una decena?","options":["10","100","1"],"answer":"A","hint":"Lee el nombre de cada posición desde la derecha.","level":2},{"id":"p-place:q2","question":"305 se descompone como…","options":["30 + 5","300 + 50","300 + 5"],"answer":"C","hint":"Lee el nombre de cada posición desde la derecha.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-fractions","stage":"primaria","subject":"Matemáticas","title":"Las fracciones","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Las fracciones","fracciones","fraccion","partes de un todo"],"explanation":"Una fracción puede representar partes iguales de una unidad. El denominador indica en cuántas partes iguales se divide la unidad; el numerador, cuántas partes consideramos. Siempre hay que saber cuál es la unidad.","simpler":"Divide una barra en partes iguales. El número de abajo dice cuántas partes tiene; el de arriba, cuántas tomas.","example":"Si una barra se divide en 4 partes iguales y tomas 3, tomas 3/4 de la barra.","why":"Sin una unidad de referencia, decir «la mitad» no basta para saber qué cantidad concreta tenemos.","misconception":"Las partes de la unidad deben ser iguales en esta representación.","hints":["Distingue el número de partes de la unidad y las partes que tomas.","Divide una barra en partes iguales. El número de abajo dice cuántas partes tiene; el de arriba, cuántas tomas.","Si una barra se divide en 4 partes iguales y tomas 3, tomas 3/4 de la barra."],"quiz":[{"id":"p-fractions:q0","question":"En 3/4, ¿cuál es el denominador?","options":["3","7","4"],"answer":"C","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":1},{"id":"p-fractions:q1","question":"En 2/5, consideramos…","options":["2 de las 5 partes iguales","5 de 2 partes","Siempre 2 unidades enteras"],"answer":"A","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":2},{"id":"p-fractions:q2","question":"Para comparar dibujos de fracciones, la unidad debe ser…","options":["De cualquier tamaño sin indicarlo","La misma o estar claramente definida","Siempre una pizza"],"answer":"B","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-denominator","stage":"primaria","subject":"Matemáticas","title":"El denominador","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El denominador","denominador","denominadores"],"explanation":"El denominador es el número de abajo en una fracción. Al representar partes de una unidad, dice en cuántas partes iguales la dividimos. Con la misma unidad, dividir en más partes produce partes más pequeñas.","simpler":"En 1/4, el 4 significa que has dividido la unidad en cuatro partes iguales.","example":"Imagina dos barras iguales: divide una en 2 partes y otra en 4. Un cuarto es más pequeño que un medio.","why":"Al repartir la misma unidad entre más partes, cada parte tiene que ser menor.","misconception":"Un denominador mayor no implica una fracción mayor si el numerador es el mismo y positivo.","hints":["Mira el número situado debajo de la línea de fracción.","En 1/4, el 4 significa que has dividido la unidad en cuatro partes iguales.","Imagina dos barras iguales: divide una en 2 partes y otra en 4. Un cuarto es más pequeño que un medio."],"quiz":[{"id":"p-denominator:q0","question":"En 5/8, ¿cuál es el denominador?","options":["5","8","13"],"answer":"B","hint":"Mira el número situado debajo de la línea de fracción.","level":1},{"id":"p-denominator:q1","question":"Con barras iguales, ¿qué parte es mayor?","options":["1/2","1/4","Son siempre iguales"],"answer":"A","hint":"Mira el número situado debajo de la línea de fracción.","level":2},{"id":"p-denominator:q2","question":"El denominador indica…","options":["Las partes tomadas siempre","El color de las partes","Las partes iguales en que se divide la unidad"],"answer":"C","hint":"Mira el número situado debajo de la línea de fracción.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-equivalent","stage":"primaria","subject":"Matemáticas","title":"Fracciones equivalentes","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Fracciones equivalentes","fracciones equivalentes","equivalencia de fracciones"],"explanation":"Dos fracciones son equivalentes si representan el mismo número. Puedes obtener una equivalente multiplicando numerador y denominador por el mismo número distinto de cero. No basta con cambiar solo uno.","simpler":"Puedes partir cada trozo en trozos más pequeños sin cambiar lo que tenías.","example":"La mitad de una barra es lo mismo que dos cuartos: 1/2 = 2/4.","why":"Multiplicar arriba y abajo por el mismo factor equivale a multiplicar la fracción por uno.","misconception":"Sumar el mismo número al numerador y al denominador no conserva siempre el valor.","hints":["Aplica el mismo factor arriba y abajo.","Puedes partir cada trozo en trozos más pequeños sin cambiar lo que tenías.","La mitad de una barra es lo mismo que dos cuartos: 1/2 = 2/4."],"quiz":[{"id":"p-equivalent:q0","question":"¿Cuál equivale a 1/2?","options":["1/4","3/4","2/4"],"answer":"C","hint":"Aplica el mismo factor arriba y abajo.","level":1},{"id":"p-equivalent:q1","question":"Para pasar de 2/3 a una equivalente con denominador 6, el numerador es…","options":["4","2","6"],"answer":"A","hint":"Aplica el mismo factor arriba y abajo.","level":2},{"id":"p-equivalent:q2","question":"Multiplicar solo el denominador por 2…","options":["Conserva siempre el valor","Cambia el valor de una fracción no nula","Duplica siempre la fracción"],"answer":"B","hint":"Aplica el mismo factor arriba y abajo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-decimal","stage":"primaria","subject":"Matemáticas","title":"Números decimales","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Números decimales","decimales","numeros decimales"],"explanation":"Los decimales amplían el valor posicional a partes de la unidad. Tras la coma aparecen décimas, centésimas y milésimas. Para compararlos, alinea las posiciones, no cuentes solo las cifras.","simpler":"Una décima es una de diez partes iguales. Una centésima es una de cien.","example":"0,5 y 0,50 representan la misma cantidad: cinco décimas son cincuenta centésimas.","why":"Cada posición a la derecha representa una parte diez veces menor que la anterior.","misconception":"Tener más cifras decimales no significa ser mayor.","hints":["Compara primero unidades, luego décimas y después centésimas.","Una décima es una de diez partes iguales. Una centésima es una de cien.","0,5 y 0,50 representan la misma cantidad: cinco décimas son cincuenta centésimas."],"quiz":[{"id":"p-decimal:q0","question":"¿Qué número es mayor?","options":["0,7","0,65","Son iguales"],"answer":"A","hint":"Compara primero unidades, luego décimas y después centésimas.","level":1},{"id":"p-decimal:q1","question":"0,50 equivale a…","options":["5","50","0,5"],"answer":"C","hint":"Compara primero unidades, luego décimas y después centésimas.","level":2},{"id":"p-decimal:q2","question":"La primera cifra tras la coma representa…","options":["Centenas","Décimas","Unidades"],"answer":"B","hint":"Compara primero unidades, luego décimas y después centésimas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-percent","stage":"primaria","subject":"Matemáticas","title":"Porcentajes","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Porcentajes","porcentajes","porcentaje","tanto por ciento"],"explanation":"Un porcentaje expresa una cantidad por cada cien. Para calcular un porcentaje de una cantidad puedes multiplicarla por el porcentaje y dividir entre cien. El total de referencia importa.","simpler":"El 25 % significa 25 de cada 100, es decir, una cuarta parte.","example":"El 20 % de 50 es 10: 50 × 20 ÷ 100 = 10.","why":"El porcentaje compara una parte con un total usando siempre cien como referencia.","misconception":"El mismo porcentaje de dos totales distintos puede dar cantidades distintas.","hints":["Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","El 25 % significa 25 de cada 100, es decir, una cuarta parte.","El 20 % de 50 es 10: 50 × 20 ÷ 100 = 10."],"quiz":[{"id":"p-percent:q0","question":"¿Cuánto es el 50 % de 80?","options":["20","40","50"],"answer":"B","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":1},{"id":"p-percent:q1","question":"El 25 % equivale a…","options":["Una cuarta parte","La mitad","El doble"],"answer":"A","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":2},{"id":"p-percent:q2","question":"El 10 % de 200 es…","options":["2","10","20"],"answer":"C","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-prime","stage":"primaria","subject":"Matemáticas","title":"Números primos","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Números primos","numeros primos","numero primo","primos"],"explanation":"Un número primo es un número natural mayor que 1 que tiene exactamente dos divisores positivos: 1 y él mismo. El 2 es primo y es el único primo par. El 1 no es primo.","simpler":"Un primo solo puede repartirse exactamente en grupos de 1 o en un único grupo con todo.","example":"El 7 solo tiene como divisores positivos 1 y 7. El 8 no es primo, porque también se divide exactamente entre 2 y 4.","why":"Tener exactamente dos divisores diferencia a los primos de los compuestos y del número 1.","misconception":"No todos los impares son primos: 9 = 3 × 3.","hints":["Cuenta los divisores positivos, no solo si el número es impar.","Un primo solo puede repartirse exactamente en grupos de 1 o en un único grupo con todo.","El 7 solo tiene como divisores positivos 1 y 7. El 8 no es primo, porque también se divide exactamente entre 2 y 4."],"quiz":[{"id":"p-prime:q0","question":"¿Cuál es primo?","options":["9","15","7"],"answer":"C","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":1},{"id":"p-prime:q1","question":"¿El 1 es primo?","options":["No","Sí","Solo a veces"],"answer":"A","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":2},{"id":"p-prime:q2","question":"¿Cuál es el único primo par?","options":["4","2","6"],"answer":"B","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-perimeter","stage":"primaria","subject":"Matemáticas","title":"El perímetro","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El perímetro","perimetro","perimetros"],"explanation":"El perímetro es la longitud del contorno de una figura. Se calcula sumando las longitudes de todos sus lados. Sus unidades son de longitud, como centímetros o metros.","simpler":"Imagina una cuerda rodeando la figura. Su longitud es el perímetro.","example":"Un rectángulo de 5 cm por 3 cm tiene perímetro 5 + 3 + 5 + 3 = 16 cm.","why":"Sumar los lados equivale a sumar todos los tramos del recorrido alrededor de la figura.","misconception":"Perímetro y área miden cosas diferentes.","hints":["Recorre el borde y no olvides ningún lado.","Imagina una cuerda rodeando la figura. Su longitud es el perímetro.","Un rectángulo de 5 cm por 3 cm tiene perímetro 5 + 3 + 5 + 3 = 16 cm."],"quiz":[{"id":"p-perimeter:q0","question":"Un cuadrado de lado 4 cm tiene perímetro…","options":["8 cm","16 cm","16 cm²"],"answer":"B","hint":"Recorre el borde y no olvides ningún lado.","level":1},{"id":"p-perimeter:q1","question":"El perímetro mide…","options":["El contorno","La superficie interior","El volumen"],"answer":"A","hint":"Recorre el borde y no olvides ningún lado.","level":2},{"id":"p-perimeter:q2","question":"Un triángulo con lados de 3, 4 y 5 cm tiene perímetro…","options":["20 cm","60 cm","12 cm"],"answer":"C","hint":"Recorre el borde y no olvides ningún lado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-area","stage":"primaria","subject":"Matemáticas","title":"El área","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El área","area","areas","area del rectangulo"],"explanation":"El área mide la superficie que ocupa una figura. Usamos unidades cuadradas. En un rectángulo, área = base × altura, siempre con medidas en la misma unidad.","simpler":"Cuenta cuántos cuadrados de una unidad cubren el interior sin huecos ni solapamientos.","example":"Un rectángulo de 4 cm por 3 cm se cubre con 12 cuadrados de 1 cm²: su área es 12 cm².","why":"Multiplicar filas por cuadrados de cada fila cuenta todos los cuadrados que cubren la superficie.","misconception":"Sumar base y altura no da el área de un rectángulo.","hints":["Piensa en filas y columnas de cuadrados iguales.","Cuenta cuántos cuadrados de una unidad cubren el interior sin huecos ni solapamientos.","Un rectángulo de 4 cm por 3 cm se cubre con 12 cuadrados de 1 cm²: su área es 12 cm²."],"quiz":[{"id":"p-area:q0","question":"El área de un rectángulo de 6 m por 2 m es…","options":["8 m","12 m","12 m²"],"answer":"C","hint":"Piensa en filas y columnas de cuadrados iguales.","level":1},{"id":"p-area:q1","question":"El área se expresa en…","options":["Unidades cuadradas","Solo unidades de longitud","Grados"],"answer":"A","hint":"Piensa en filas y columnas de cuadrados iguales.","level":2},{"id":"p-area:q2","question":"Un cuadrado de lado 5 cm tiene área…","options":["20 cm²","25 cm²","10 cm²"],"answer":"B","hint":"Piensa en filas y columnas de cuadrados iguales.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-measure","stage":"primaria","subject":"Matemáticas","title":"Unidades de longitud","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Unidades de longitud","longitud","unidades de longitud","metros y centimetros"],"explanation":"Medir una longitud es compararla con una unidad. Un metro equivale a 100 centímetros y un kilómetro a 1000 metros. Al cambiar de unidad, la longitud real no cambia.","simpler":"Puedes medir el mismo objeto con unidades grandes o pequeñas: necesitarás más unidades pequeñas.","example":"Una cinta de 2 metros mide también 200 centímetros.","why":"La medida numérica depende de la unidad elegida: unidades menores producen números mayores para la misma longitud.","misconception":"Convertir unidades no altera el tamaño del objeto.","hints":["Recuerda cuántas unidades pequeñas forman una grande.","Puedes medir el mismo objeto con unidades grandes o pequeñas: necesitarás más unidades pequeñas.","Una cinta de 2 metros mide también 200 centímetros."],"quiz":[{"id":"p-measure:q0","question":"1 metro equivale a…","options":["10 cm","100 cm","1000 cm"],"answer":"B","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":1},{"id":"p-measure:q1","question":"2 kilómetros equivalen a…","options":["2000 metros","200 metros","20 metros"],"answer":"A","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":2},{"id":"p-measure:q2","question":"Al expresar una distancia en centímetros en vez de metros…","options":["La distancia crece","El objeto cambia","Cambia el número, no la distancia"],"answer":"C","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-clock","stage":"primaria","subject":"Matemáticas","title":"Leer la hora","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Leer la hora","la hora","leer el reloj","horas y minutos"],"explanation":"Una hora tiene 60 minutos y un minuto 60 segundos. En un reloj de agujas, la aguja larga indica los minutos y la corta las horas. No confundas la hora del día con una duración.","simpler":"La aguja larga da una vuelta en una hora. Media hora son 30 minutos.","example":"Si empiezas a las 10:15 y pasan 30 minutos, serán las 10:45.","why":"El reloj combina unidades distintas; por eso al llegar a 60 minutos se completa otra hora.","misconception":"Una hora no tiene cien minutos.","hints":["Calcula cuántos minutos faltan y comprueba si cambia la hora.","La aguja larga da una vuelta en una hora. Media hora son 30 minutos.","Si empiezas a las 10:15 y pasan 30 minutos, serán las 10:45."],"quiz":[{"id":"p-clock:q0","question":"Media hora son…","options":["15 minutos","60 minutos","30 minutos"],"answer":"C","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":1},{"id":"p-clock:q1","question":"De 9:10 a 9:40 pasan…","options":["30 minutos","40 minutos","50 minutos"],"answer":"A","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":2},{"id":"p-clock:q2","question":"Una hora tiene…","options":["100 minutos","60 minutos","24 minutos"],"answer":"B","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-mean","stage":"primaria","subject":"Matemáticas","title":"La media aritmética","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["La media aritmética","media aritmetica","promedio"],"explanation":"La media aritmética se calcula sumando los valores y dividiendo entre el número de datos. Representa un reparto igual del total, pero no cuenta por sí sola toda la información.","simpler":"Junta todas las cantidades y reparte el total en tantos grupos iguales como datos había.","example":"Para 4, 6 y 8, la media es (4 + 6 + 8) ÷ 3 = 6.","why":"La media es el valor que tendría cada dato si redistribuyéramos el total por igual.","misconception":"La media puede no coincidir con ninguno de los datos originales.","hints":["Cuenta los datos antes de dividir la suma.","Junta todas las cantidades y reparte el total en tantos grupos iguales como datos había.","Para 4, 6 y 8, la media es (4 + 6 + 8) ÷ 3 = 6."],"quiz":[{"id":"p-mean:q0","question":"La media de 2 y 8 es…","options":["10","5","6"],"answer":"B","hint":"Cuenta los datos antes de dividir la suma.","level":1},{"id":"p-mean:q1","question":"¿Por qué dividimos entre 3 con tres datos?","options":["Porque hay tres valores","Porque el mayor es tres","Porque siempre se divide entre tres"],"answer":"A","hint":"Cuenta los datos antes de dividir la suma.","level":2},{"id":"p-mean:q2","question":"La media de 5, 5 y 5 es…","options":["15","3","5"],"answer":"C","hint":"Cuenta los datos antes de dividir la suma.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-noun","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El sustantivo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El sustantivo","sustantivo","sustantivos","nombres en gramatica"],"explanation":"Un sustantivo es una palabra que nombra personas, animales, objetos, lugares o ideas. Puede ser común, como ciudad, o propio, como Málaga. Para identificarlo, observa qué nombra y cómo funciona en la oración.","simpler":"Un sustantivo sirve para nombrar: niña, perro, mesa, alegría.","example":"En «La niña abre la mochila», niña y mochila son sustantivos. «Abre» indica una acción y es un verbo.","why":"Las categorías gramaticales describen el comportamiento de las palabras, no solo si podemos ver aquello que nombran.","misconception":"No todos los sustantivos nombran cosas que se puedan tocar.","hints":["Busca la palabra que nombra una entidad o una idea.","Un sustantivo sirve para nombrar: niña, perro, mesa, alegría.","En «La niña abre la mochila», niña y mochila son sustantivos. «Abre» indica una acción y es un verbo."],"quiz":[{"id":"p-noun:q0","question":"¿Cuál es un sustantivo?","options":["Correr","Mochila","Azul"],"answer":"B","hint":"Busca la palabra que nombra una entidad o una idea.","level":1},{"id":"p-noun:q1","question":"Málaga es un nombre…","options":["Propio","Verbal","Adjetivo"],"answer":"A","hint":"Busca la palabra que nombra una entidad o una idea.","level":2},{"id":"p-noun:q2","question":"En «El perro duerme», el sustantivo es…","options":["El","Duerme","Perro"],"answer":"C","hint":"Busca la palabra que nombra una entidad o una idea.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-adjective","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El adjetivo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El adjetivo","adjetivo","adjetivos"],"explanation":"Un adjetivo aporta una cualidad o característica de un sustantivo. Normalmente concuerda con él en género y número cuando su forma permite esos cambios.","simpler":"El sustantivo nombra algo y el adjetivo dice cómo es.","example":"En «las montañas altas», montañas es el sustantivo y altas es el adjetivo. Ambos están en femenino plural.","why":"La concordancia ayuda a reconocer qué palabras están relacionadas dentro de un grupo nominal.","misconception":"Una misma palabra puede tener funciones distintas según la oración.","hints":["Pregunta qué palabra describe al sustantivo.","El sustantivo nombra algo y el adjetivo dice cómo es.","En «las montañas altas», montañas es el sustantivo y altas es el adjetivo. Ambos están en femenino plural."],"quiz":[{"id":"p-adjective:q0","question":"En «un coche rápido», el adjetivo es…","options":["Coche","Un","Rápido"],"answer":"C","hint":"Pregunta qué palabra describe al sustantivo.","level":1},{"id":"p-adjective:q1","question":"¿Qué expresión concuerda?","options":["Las casas blancas","Las casas blanco","La casas blancas"],"answer":"A","hint":"Pregunta qué palabra describe al sustantivo.","level":2},{"id":"p-adjective:q2","question":"El adjetivo aporta…","options":["Una operación","Una característica del sustantivo","Siempre una acción"],"answer":"B","hint":"Pregunta qué palabra describe al sustantivo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-verb","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El verbo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El verbo","verbo","verbos"],"explanation":"El verbo puede expresar una acción, un estado o un proceso. Su forma puede indicar persona, número y tiempo. No todos los verbos describen movimientos.","simpler":"Correr es una acción; estar puede expresar un estado. Los dos son verbos.","example":"«Ayer jugamos» se sitúa en el pasado; «mañana jugaremos», en el futuro.","why":"La conjugación sitúa lo que se dice en el tiempo y lo relaciona con quienes participan.","misconception":"Ser y estar también son verbos aunque no describan una acción visible.","hints":["Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","Correr es una acción; estar puede expresar un estado. Los dos son verbos.","«Ayer jugamos» se sitúa en el pasado; «mañana jugaremos», en el futuro."],"quiz":[{"id":"p-verb:q0","question":"En «Marta lee», el verbo es…","options":["Lee","Marta","Ninguno"],"answer":"A","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":1},{"id":"p-verb:q1","question":"«Jugaremos» indica normalmente…","options":["Pasado","Presente","Futuro"],"answer":"C","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":2},{"id":"p-verb:q2","question":"¿Todos los verbos indican movimiento?","options":["Sí","No","Solo en plural"],"answer":"B","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-subject","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Sujeto y predicado","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Sujeto y predicado","sujeto y predicado","el sujeto","el predicado"],"explanation":"En muchas oraciones, el sujeto es el grupo que concuerda en número y persona con el verbo. El predicado contiene el verbo y lo que se dice del sujeto. El sujeto puede no estar escrito y hay oraciones impersonales.","simpler":"Busca primero el verbo. Después observa qué grupo concuerda con él.","example":"En «Los pájaros cantan», «los pájaros» es el sujeto y «cantan» el predicado. En «Llueve» no hay un sujeto que realice la lluvia.","why":"La concordancia proporciona una pista gramatical más fiable que identificar siempre un supuesto agente.","misconception":"No basta preguntar quién hace la acción: no todos los verbos expresan acciones.","hints":["Comprueba la concordancia con el verbo.","Busca primero el verbo. Después observa qué grupo concuerda con él.","En «Los pájaros cantan», «los pájaros» es el sujeto y «cantan» el predicado. En «Llueve» no hay un sujeto que realice la lluvia."],"quiz":[{"id":"p-subject:q0","question":"El sujeto de «Las niñas leen» es…","options":["Leen","Las niñas","Las"],"answer":"B","hint":"Comprueba la concordancia con el verbo.","level":1},{"id":"p-subject:q1","question":"En «El gato duerme», el predicado es…","options":["Duerme","El gato","El"],"answer":"A","hint":"Comprueba la concordancia con el verbo.","level":2},{"id":"p-subject:q2","question":"¿Toda oración tiene un sujeto escrito?","options":["Sí","Solo si es corta","No"],"answer":"C","hint":"Comprueba la concordancia con el verbo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-accent","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Acentuación","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Acentuación","acentuacion","tildes","agudas llanas y esdrujulas"],"explanation":"La sílaba tónica es la que pronunciamos con más fuerza. Las agudas llevan tilde si terminan en vocal, n o s; las llanas, si no terminan en vocal, n o s. Las esdrújulas siempre llevan tilde. Existen casos especiales que se estudian aparte.","simpler":"Escucha dónde suena la fuerza de la palabra. Después aplica la regla de su grupo.","example":"«Café» es aguda y termina en vocal; «árbol» es llana y termina en l; «música» es esdrújula.","why":"La tilde sigue convenciones de escritura y no aparece en todas las sílabas tónicas.","misconception":"Acento prosódico y tilde no son lo mismo.","hints":["Pronuncia la palabra antes de mirar su última letra.","Escucha dónde suena la fuerza de la palabra. Después aplica la regla de su grupo.","«Café» es aguda y termina en vocal; «árbol» es llana y termina en l; «música» es esdrújula."],"quiz":[{"id":"p-accent:q0","question":"¿Qué palabra es esdrújula?","options":["Papel","Casa","Música"],"answer":"C","hint":"Pronuncia la palabra antes de mirar su última letra.","level":1},{"id":"p-accent:q1","question":"«Café» lleva tilde porque es…","options":["Aguda terminada en vocal","Llana terminada en consonante","Monosílaba siempre"],"answer":"A","hint":"Pronuncia la palabra antes de mirar su última letra.","level":2},{"id":"p-accent:q2","question":"¿Dónde está la sílaba tónica de árbol?","options":["En bol","En ár","No tiene"],"answer":"B","hint":"Pronuncia la palabra antes de mirar su última letra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-summary","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Hacer un resumen","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Hacer un resumen","resumen","resumir","hacer un resumen"],"explanation":"Resumir consiste en expresar las ideas principales de un texto con menos palabras, sin cambiar su sentido. Primero comprende, después selecciona lo esencial y finalmente redacta con tus palabras. No añadas datos que no aparecen.","simpler":"Cuenta lo más importante del texto, sin copiarlo entero ni inventar detalles.","example":"Si un texto explica que las abejas transportan polen al visitar flores, el resumen debe conservar esa idea; no necesita repetir cada ejemplo.","why":"Seleccionar lo esencial exige comprender las relaciones entre las ideas, no únicamente reducir la longitud.","misconception":"Un resumen no es solo quitar frases al azar.","hints":["Pregúntate qué información no puede faltar para entender el texto.","Cuenta lo más importante del texto, sin copiarlo entero ni inventar detalles.","Si un texto explica que las abejas transportan polen al visitar flores, el resumen debe conservar esa idea; no necesita repetir cada ejemplo."],"quiz":[{"id":"p-summary:q0","question":"Un resumen debe conservar…","options":["Todas las palabras","Las ideas principales","Solo el título"],"answer":"B","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":1},{"id":"p-summary:q1","question":"¿Qué haces primero?","options":["Comprender el texto","Inventar un final","Acortarlo sin leer"],"answer":"A","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":2},{"id":"p-summary:q2","question":"¿Debemos añadir datos nuevos al resumen?","options":["Siempre","Para hacerlo más largo","No"],"answer":"C","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-water","stage":"primaria","subject":"Conocimiento del Medio","title":"El ciclo del agua","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El ciclo del agua","ciclo del agua","el ciclo del agua"],"explanation":"El agua circula entre la superficie terrestre y la atmósfera. Puede evaporarse, condensarse formando gotitas o cristales y caer como precipitación. También se infiltra en el suelo o fluye hacia ríos y mares. No es una única ruta igual para cada gota.","simpler":"El agua puede pasar al aire como vapor, formar nubes y volver a la superficie como lluvia o nieve.","example":"Un charco disminuye cuando parte del agua se evapora. El vapor puede condensarse y participar en la formación de nubes.","why":"La energía solar y la gravedad impulsan distintas partes del ciclo; el agua cambia de lugar y de estado.","misconception":"Las nubes no son vapor de agua visible: contienen gotitas o cristales.","hints":["Sigue el agua y nombra cada cambio.","El agua puede pasar al aire como vapor, formar nubes y volver a la superficie como lluvia o nieve.","Un charco disminuye cuando parte del agua se evapora. El vapor puede condensarse y participar en la formación de nubes."],"quiz":[{"id":"p-water:q0","question":"El paso de agua líquida a vapor se llama…","options":["Condensación","Precipitación","Evaporación"],"answer":"C","hint":"Sigue el agua y nombra cada cambio.","level":1},{"id":"p-water:q1","question":"La lluvia es un ejemplo de…","options":["Precipitación","Evaporación","Infiltración siempre"],"answer":"A","hint":"Sigue el agua y nombra cada cambio.","level":2},{"id":"p-water:q2","question":"El agua que entra en el suelo realiza…","options":["Fusión","Infiltración","Combustión"],"answer":"B","hint":"Sigue el agua y nombra cada cambio.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-photosynthesis","stage":"primaria","subject":"Conocimiento del Medio","title":"La fotosíntesis","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La fotosíntesis","fotosintesis","la fotosintesis"],"explanation":"En la fotosíntesis, las plantas y otros organismos fotosintéticos utilizan energía luminosa para formar materia orgánica a partir de agua y dióxido de carbono. En la fotosíntesis oxigénica se libera oxígeno. Las plantas también respiran.","simpler":"La planta usa luz como energía para fabricar materia orgánica con agua y dióxido de carbono.","example":"Las hojas de una planta reciben luz; el agua llega desde las raíces y el dióxido de carbono entra principalmente por pequeños poros.","why":"La luz aporta energía, pero la materia orgánica se construye con materia: principalmente agua y dióxido de carbono.","misconception":"Las plantas no se alimentan simplemente de la luz ni dejan de respirar por hacer fotosíntesis.","hints":["Distingue los materiales que entran y la energía que permite transformarlos.","La planta usa luz como energía para fabricar materia orgánica con agua y dióxido de carbono.","Las hojas de una planta reciben luz; el agua llega desde las raíces y el dióxido de carbono entra principalmente por pequeños poros."],"quiz":[{"id":"p-photosynthesis:q0","question":"¿Qué aporta la luz?","options":["Tierra","Energía","Agua"],"answer":"B","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":1},{"id":"p-photosynthesis:q1","question":"¿Qué gas utilizan para formar materia orgánica?","options":["Dióxido de carbono","Helio","Neón"],"answer":"A","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":2},{"id":"p-photosynthesis:q2","question":"¿Las plantas también respiran?","options":["No","Solo de pequeñas","Sí"],"answer":"C","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-states","stage":"primaria","subject":"Conocimiento del Medio","title":"Estados de la materia","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Estados de la materia","estados de la materia","solido liquido y gas"],"explanation":"La materia puede presentarse en distintos estados. En un sólido se conserva aproximadamente la forma y el volumen; un líquido conserva aproximadamente el volumen y adopta la forma del recipiente; un gas se expande para ocupar el espacio disponible.","simpler":"Un cubito mantiene su forma; el agua líquida se adapta al vaso; un gas puede extenderse.","example":"El hielo se funde y se convierte en agua líquida. Sigue siendo agua: ha cambiado de estado.","why":"Al cambiar la energía y las condiciones, cambia la organización y movilidad de las partículas.","misconception":"Un cambio de estado no implica necesariamente una nueva sustancia.","hints":["Pregunta si cambió la sustancia o solo su estado.","Un cubito mantiene su forma; el agua líquida se adapta al vaso; un gas puede extenderse.","El hielo se funde y se convierte en agua líquida. Sigue siendo agua: ha cambiado de estado."],"quiz":[{"id":"p-states:q0","question":"El paso de sólido a líquido se llama…","options":["Fusión","Evaporación","Condensación"],"answer":"A","hint":"Pregunta si cambió la sustancia o solo su estado.","level":1},{"id":"p-states:q1","question":"¿Qué estado ocupa el espacio disponible?","options":["Sólido","Líquido siempre","Gas"],"answer":"C","hint":"Pregunta si cambió la sustancia o solo su estado.","level":2},{"id":"p-states:q2","question":"Al fundirse el hielo…","options":["Deja de ser agua","Cambia de estado","Se convierte en madera"],"answer":"B","hint":"Pregunta si cambió la sustancia o solo su estado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-ecosystem","stage":"primaria","subject":"Conocimiento del Medio","title":"Los ecosistemas","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los ecosistemas","ecosistema","ecosistemas"],"explanation":"Un ecosistema incluye seres vivos, el medio físico y sus relaciones. El agua, la luz y el suelo influyen en los organismos; los organismos también modifican su entorno. Cambiar un elemento puede afectar a otros.","simpler":"No estudias solo los animales: también dónde viven y cómo se relacionan.","example":"En una charca hay plantas, insectos y otros organismos, junto con agua, luz y temperatura. Sus relaciones forman parte del ecosistema.","why":"Las relaciones hacen que un cambio se propague; por eso estudiamos el sistema y no solo cada pieza por separado.","misconception":"Un ecosistema no es únicamente una lista de especies.","hints":["Busca tanto los componentes vivos como los no vivos.","No estudias solo los animales: también dónde viven y cómo se relacionan.","En una charca hay plantas, insectos y otros organismos, junto con agua, luz y temperatura. Sus relaciones forman parte del ecosistema."],"quiz":[{"id":"p-ecosystem:q0","question":"¿Qué incluye un ecosistema?","options":["Solo animales","Solo agua","Seres vivos, medio y relaciones"],"answer":"C","hint":"Busca tanto los componentes vivos como los no vivos.","level":1},{"id":"p-ecosystem:q1","question":"La luz es un factor…","options":["Del medio físico","Siempre un animal","Sin influencia"],"answer":"A","hint":"Busca tanto los componentes vivos como los no vivos.","level":2},{"id":"p-ecosystem:q2","question":"Un cambio en el agua puede afectar…","options":["Solo al color","A distintos organismos","A ninguno nunca"],"answer":"B","hint":"Busca tanto los componentes vivos como los no vivos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-maps","stage":"primaria","subject":"Conocimiento del Medio","title":"Los mapas","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los mapas","mapas","mapa","escala de un mapa"],"explanation":"Un mapa representa un espacio de forma reducida y selecciona cierta información. La leyenda explica sus símbolos y la escala relaciona distancias del mapa con distancias reales. Hay mapas que sirven para tareas diferentes.","simpler":"La leyenda te dice qué significa cada dibujo. La escala indica cuánto se ha reducido la distancia.","example":"Si 1 cm en el mapa representa 1 km real, dos puntos separados 3 cm están a 3 km en línea recta según esa escala.","why":"Un mapa simplifica la realidad para una finalidad; elegir el tipo adecuado evita interpretaciones equivocadas.","misconception":"La distancia en línea recta puede diferir de la distancia por carretera.","hints":["Lee antes la leyenda y la escala.","La leyenda te dice qué significa cada dibujo. La escala indica cuánto se ha reducido la distancia.","Si 1 cm en el mapa representa 1 km real, dos puntos separados 3 cm están a 3 km en línea recta según esa escala."],"quiz":[{"id":"p-maps:q0","question":"¿Para qué sirve la leyenda?","options":["Para medir el tiempo","Para interpretar símbolos","Para cambiar el norte"],"answer":"B","hint":"Lee antes la leyenda y la escala.","level":1},{"id":"p-maps:q1","question":"Con 1 cm = 1 km, 4 cm representan…","options":["4 km","40 km","400 km"],"answer":"A","hint":"Lee antes la leyenda y la escala.","level":2},{"id":"p-maps:q2","question":"La escala relaciona…","options":["Colores y animales","Días y horas","Distancias representadas y reales"],"answer":"C","hint":"Lee antes la leyenda y la escala.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-to-be","stage":"primaria","subject":"Lengua Extranjera: Inglés","title":"El verbo to be","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El verbo to be","to be","verbo to be","am is are"],"explanation":"To be puede corresponder a ser o estar según el contexto. En presente usamos I am; he, she, it is; y you, we, they are. Para preguntar, colocamos esa forma verbal antes del sujeto.","simpler":"Recuerda tres formas: am con I, is con he/she/it y are con you/we/they.","example":"«She is happy» significa «Ella está contenta». La pregunta es «Is she happy?».","why":"La forma verbal depende del sujeto; en estas preguntas no añadimos do porque invertimos sujeto y to be.","misconception":"To be no se traduce siempre con la misma palabra española.","hints":["Identifica primero el sujeto.","Recuerda tres formas: am con I, is con he/she/it y are con you/we/they.","«She is happy» significa «Ella está contenta». La pregunta es «Is she happy?»."],"quiz":[{"id":"p-to-be:q0","question":"Completa: I ___ ready.","options":["Is","Are","Am"],"answer":"C","hint":"Identifica primero el sujeto.","level":1},{"id":"p-to-be:q1","question":"Completa: They ___ students.","options":["Are","Is","Am"],"answer":"A","hint":"Identifica primero el sujeto.","level":2},{"id":"p-to-be:q2","question":"¿Qué pregunta está bien formada?","options":["She is happy? siempre","Is she happy?","Does she is happy?"],"answer":"B","hint":"Identifica primero el sujeto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-integers","stage":"eso","subject":"Matemáticas","title":"Números enteros","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Números enteros","numeros enteros","enteros","negativos"],"explanation":"Los enteros incluyen negativos, cero y positivos. En la recta numérica, un número situado más a la derecha es mayor. Para sumar un negativo puedes desplazarte a la izquierda.","simpler":"Los negativos están a la izquierda del cero. Entre −2 y −5, −2 está más a la derecha y es mayor.","example":"Partiendo de 3, sumar −5 significa moverte cinco unidades a la izquierda: llegas a −2.","why":"El orden depende de la posición, mientras que el valor absoluto mide la distancia al cero.","misconception":"El entero con mayor valor absoluto no es siempre el mayor.","hints":["Dibuja una recta y sitúa el cero.","Los negativos están a la izquierda del cero. Entre −2 y −5, −2 está más a la derecha y es mayor.","Partiendo de 3, sumar −5 significa moverte cinco unidades a la izquierda: llegas a −2."],"quiz":[{"id":"e-integers:q0","question":"¿Cuál es mayor?","options":["−5","−2","−8"],"answer":"B","hint":"Dibuja una recta y sitúa el cero.","level":1},{"id":"e-integers:q1","question":"3 + (−5) es…","options":["−2","2","8"],"answer":"A","hint":"Dibuja una recta y sitúa el cero.","level":2},{"id":"e-integers:q2","question":"El opuesto de −7 es…","options":["−14","0","7"],"answer":"C","hint":"Dibuja una recta y sitúa el cero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-equation","stage":"eso","subject":"Matemáticas","title":"Ecuaciones de primer grado","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Ecuaciones de primer grado","ecuaciones de primer grado","ecuacion lineal","ecuaciones lineales"],"explanation":"Una ecuación afirma que dos expresiones tienen el mismo valor. Resolverla es encontrar el valor de la incógnita que hace verdadera esa igualdad. Puedes operar en ambos miembros de forma equivalente para conservarla.","simpler":"Piensa en una balanza: cambia ambos lados de la misma manera para que sigan equilibrados.","example":"En 2x + 3 = 11, restamos 3 en ambos lados: 2x = 8. Después dividimos ambos por 2: x = 4.","why":"Las transformaciones equivalentes conservan el conjunto de soluciones cuando cumplen sus condiciones.","misconception":"«Pasar cambiando de signo» es una abreviatura, no una regla mágica sin operación equivalente.","hints":["Deshaz las operaciones en orden inverso y conserva la igualdad.","Piensa en una balanza: cambia ambos lados de la misma manera para que sigan equilibrados.","En 2x + 3 = 11, restamos 3 en ambos lados: 2x = 8. Después dividimos ambos por 2: x = 4."],"quiz":[{"id":"e-equation:q0","question":"La solución de x + 5 = 9 es…","options":["14","5","4"],"answer":"C","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":1},{"id":"e-equation:q1","question":"Para conservar una igualdad al restar 3, lo hacemos…","options":["En ambos miembros","Solo a la izquierda","Solo a la derecha"],"answer":"A","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":2},{"id":"e-equation:q2","question":"¿Cómo comprobamos una solución?","options":["Mirando solo el signo","Sustituyendo en la ecuación original","Sumando todos los números"],"answer":"B","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-powers","stage":"eso","subject":"Matemáticas","title":"Potencias","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Potencias","potencias","potencia","exponentes"],"explanation":"Una potencia con exponente natural expresa un producto repetido de la base. En a elevado a n, n indica cuántos factores iguales a a se multiplican. No significa multiplicar base por exponente.","simpler":"2³ significa multiplicar tres factores iguales: 2 × 2 × 2. No significa hacer 2 × 3.","example":"3² = 3 × 3 = 9. Para una base distinta de cero, a⁰ = 1.","why":"Las reglas de potencias condensan cómo se agrupan productos de factores iguales.","misconception":"El exponente no es un factor que multiplicas directamente por la base.","hints":["Escribe el producto completo antes de calcular.","2³ significa multiplicar tres factores iguales: 2 × 2 × 2. No significa hacer 2 × 3.","3² = 3 × 3 = 9. Para una base distinta de cero, a⁰ = 1."],"quiz":[{"id":"e-powers:q0","question":"El resultado de la potencia 2³ es…","options":["8","6","9"],"answer":"A","hint":"Escribe el producto completo antes de calcular.","level":1},{"id":"e-powers:q1","question":"5² significa…","options":["5 + 5","5 × 2","5 × 5"],"answer":"C","hint":"Escribe el producto completo antes de calcular.","level":2},{"id":"e-powers:q2","question":"Para a distinto de cero, a⁰ vale…","options":["0","1","a"],"answer":"B","hint":"Escribe el producto completo antes de calcular.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-proportionality","stage":"eso","subject":"Matemáticas","title":"Proporcionalidad directa","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Proporcionalidad directa","proporcionalidad directa","proporciones"],"explanation":"Dos magnitudes son directamente proporcionales si una se obtiene multiplicando la otra por una constante. Al duplicar una, se duplica la otra. Que ambas aumenten no basta para demostrar proporcionalidad.","simpler":"Busca si el cociente entre las cantidades correspondientes es siempre el mismo.","example":"Si cada cuaderno cuesta 3 €, 2 cuestan 6 € y 5 cuestan 15 €, sin descuentos ni gastos fijos.","why":"La constante de proporcionalidad permite expresar la relación como y = kx.","misconception":"Una relación con una cuota fija inicial no suele ser proporcional directa.","hints":["Calcula cuánto corresponde a una unidad.","Busca si el cociente entre las cantidades correspondientes es siempre el mismo.","Si cada cuaderno cuesta 3 €, 2 cuestan 6 € y 5 cuestan 15 €, sin descuentos ni gastos fijos."],"quiz":[{"id":"e-proportionality:q0","question":"Con precio fijo de 4 € por pieza, 3 piezas cuestan…","options":["7 €","12 €","1 €"],"answer":"B","hint":"Calcula cuánto corresponde a una unidad.","level":1},{"id":"e-proportionality:q1","question":"En proporcionalidad directa, al duplicar una magnitud la otra…","options":["Se duplica","Se divide siempre por dos","No cambia"],"answer":"A","hint":"Calcula cuánto corresponde a una unidad.","level":2},{"id":"e-proportionality:q2","question":"¿Basta con que ambas aumenten?","options":["Sí","Solo si son positivas","No"],"answer":"C","hint":"Calcula cuánto corresponde a una unidad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-pythagoras","stage":"eso","subject":"Matemáticas","title":"Teorema de Pitágoras","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Teorema de Pitágoras","pitagoras","teorema de pitagoras"],"explanation":"En un triángulo rectángulo, el cuadrado de la hipotenusa es igual a la suma de los cuadrados de los catetos. La hipotenusa está enfrente del ángulo recto y es el lado más largo. Comprueba primero que el triángulo sea rectángulo.","simpler":"Si los catetos son a y b y la hipotenusa c, entonces a² + b² = c².","example":"Con catetos 3 y 4, c² = 9 + 16 = 25; como es una longitud positiva, c = 5.","why":"La relación se establece entre áreas de cuadrados construidos sobre los lados, no entre sus longitudes sin elevar al cuadrado.","misconception":"No sumes las longitudes de los catetos para obtener la hipotenusa.","hints":["Identifica la hipotenusa antes de sustituir los valores.","Si los catetos son a y b y la hipotenusa c, entonces a² + b² = c².","Con catetos 3 y 4, c² = 9 + 16 = 25; como es una longitud positiva, c = 5."],"quiz":[{"id":"e-pythagoras:q0","question":"Con catetos 6 y 8, la hipotenusa mide…","options":["14","2","10"],"answer":"C","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":1},{"id":"e-pythagoras:q1","question":"El teorema se aplica directamente a triángulos…","options":["Rectángulos","De cualquier tipo","Solo equiláteros"],"answer":"A","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":2},{"id":"e-pythagoras:q2","question":"La hipotenusa está…","options":["Junto al ángulo más pequeño siempre","Frente al ángulo recto","En el interior del triángulo"],"answer":"B","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-functions","stage":"eso","subject":"Matemáticas","title":"Las funciones","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Las funciones","funciones","funcion matematica"],"explanation":"Una función asigna a cada valor permitido de entrada un único valor de salida. El dominio reúne las entradas admitidas. Una fórmula, tabla o gráfica puede describir la misma relación.","simpler":"Cada entrada tiene una sola salida, aunque distintas entradas puedan tener la misma salida.","example":"En f(x) = 2x + 1, la entrada 3 produce 7. La entrada 0 produce 1.","why":"La unicidad se exige por entrada, no por salida: una misma entrada no puede producir dos salidas diferentes dentro de la misma función.","misconception":"Dos entradas pueden compartir salida sin dejar de ser una función.","hints":["Sustituye la variable por el valor de entrada.","Cada entrada tiene una sola salida, aunque distintas entradas puedan tener la misma salida.","En f(x) = 2x + 1, la entrada 3 produce 7. La entrada 0 produce 1."],"quiz":[{"id":"e-functions:q0","question":"Si f(x) = 2x + 1, f(4) vale…","options":["8","9","5"],"answer":"B","hint":"Sustituye la variable por el valor de entrada.","level":1},{"id":"e-functions:q1","question":"Cada entrada admitida debe tener…","options":["Una única salida","Todas las salidas posibles","Ninguna salida"],"answer":"A","hint":"Sustituye la variable por el valor de entrada.","level":2},{"id":"e-functions:q2","question":"El dominio contiene…","options":["Solo los resultados","Los nombres de los ejes","Las entradas permitidas"],"answer":"C","hint":"Sustituye la variable por el valor de entrada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-probability","stage":"eso","subject":"Matemáticas","title":"Probabilidad","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Probabilidad","probabilidad","probabilidades"],"explanation":"La probabilidad mide la posibilidad de un suceso. Si todos los resultados elementales son igual de probables, se calcula dividiendo casos favorables entre casos posibles. Un resultado más probable no es seguro.","simpler":"Cuenta primero las opciones posibles y después las que cumplen lo pedido, solo si todas tienen la misma posibilidad.","example":"En un dado equilibrado, obtener un número par tiene probabilidad 3/6 = 1/2.","why":"La probabilidad describe incertidumbre; las frecuencias observadas pueden variar en muestras pequeñas.","misconception":"Una probabilidad alta no garantiza que el suceso ocurra en un intento.","hints":["Comprueba la equiprobabilidad antes de contar.","Cuenta primero las opciones posibles y después las que cumplen lo pedido, solo si todas tienen la misma posibilidad.","En un dado equilibrado, obtener un número par tiene probabilidad 3/6 = 1/2."],"quiz":[{"id":"e-probability:q0","question":"En un dado equilibrado, obtener un 6 tiene probabilidad…","options":["1/2","1","1/6"],"answer":"C","hint":"Comprueba la equiprobabilidad antes de contar.","level":1},{"id":"e-probability:q1","question":"La probabilidad de un suceso imposible es…","options":["0","1","2"],"answer":"A","hint":"Comprueba la equiprobabilidad antes de contar.","level":2},{"id":"e-probability:q2","question":"La regla casos favorables/casos posibles exige…","options":["Resultados todos distintos de cero","Resultados elementales equiprobables","Que el suceso sea seguro"],"answer":"B","hint":"Comprueba la equiprobabilidad antes de contar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-cell","stage":"eso","subject":"Biología y Geología","title":"La célula","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La célula","celula","celulas","la celula"],"explanation":"La célula es la unidad estructural y funcional básica de los seres vivos. Las células tienen membrana plasmática, material genético y un medio interno donde ocurren procesos. Las eucariotas tienen núcleo; las procariotas no tienen un núcleo delimitado por membrana.","simpler":"Los seres vivos están formados por células. Algunas tienen núcleo y otras no.","example":"Una bacteria es un organismo procariota; una célula de una hoja es eucariota y suele tener pared celular y cloroplastos.","why":"El núcleo es una forma de organizar el ADN, no un requisito para que exista una célula.","misconception":"Las procariotas tienen material genético aunque carezcan de núcleo membranoso.","hints":["Distingue tener material genético de tener núcleo.","Los seres vivos están formados por células. Algunas tienen núcleo y otras no.","Una bacteria es un organismo procariota; una célula de una hoja es eucariota y suele tener pared celular y cloroplastos."],"quiz":[{"id":"e-cell:q0","question":"¿Qué tipo tiene núcleo delimitado por membrana?","options":["Eucariota","Procariota","Todas sin excepción"],"answer":"A","hint":"Distingue tener material genético de tener núcleo.","level":1},{"id":"e-cell:q1","question":"Una bacteria es normalmente…","options":["Un tejido","Una célula sin material genético","Un organismo procariota"],"answer":"C","hint":"Distingue tener material genético de tener núcleo.","level":2},{"id":"e-cell:q2","question":"¿Qué estructura delimita una célula?","options":["Solo el núcleo","La membrana plasmática","La atmósfera"],"answer":"B","hint":"Distingue tener material genético de tener núcleo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-atoms","stage":"eso","subject":"Física y Química","title":"Átomos y moléculas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Átomos y moléculas","atomos y moleculas","atomos","moleculas"],"explanation":"Un átomo es una unidad de un elemento químico. Tiene núcleo con protones y, normalmente, neutrones; los electrones ocupan regiones alrededor del núcleo. Una molécula reúne átomos enlazados. No todas las sustancias están formadas por moléculas discretas.","simpler":"Un átomo pertenece a un elemento; una molécula puede unir varios átomos.","example":"H₂O indica una molécula con dos átomos de hidrógeno y uno de oxígeno. No significa dos moléculas de agua.","why":"Las fórmulas muestran proporciones y composición; su interpretación depende del tipo de sustancia.","misconception":"Un átomo no es una pequeña esfera con órbitas planetarias exactas.","hints":["Separa elemento, átomo y molécula.","Un átomo pertenece a un elemento; una molécula puede unir varios átomos.","H₂O indica una molécula con dos átomos de hidrógeno y uno de oxígeno. No significa dos moléculas de agua."],"quiz":[{"id":"e-atoms:q0","question":"Una molécula de H₂O contiene…","options":["Dos oxígenos y un hidrógeno","Dos hidrógenos y un oxígeno","Solo hidrógeno"],"answer":"B","hint":"Separa elemento, átomo y molécula.","level":1},{"id":"e-atoms:q1","question":"La carga del protón es…","options":["Positiva","Negativa","Nula siempre"],"answer":"A","hint":"Separa elemento, átomo y molécula.","level":2},{"id":"e-atoms:q2","question":"¿Toda sustancia está hecha de moléculas discretas?","options":["Sí","Solo las sólidas","No"],"answer":"C","hint":"Separa elemento, átomo y molécula.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-density","stage":"eso","subject":"Física y Química","title":"La densidad","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La densidad","densidad","masa y volumen"],"explanation":"La densidad relaciona masa y volumen: densidad = masa/volumen. Describe cuánta masa corresponde a cada unidad de volumen. Compara valores usando las mismas unidades y teniendo en cuenta las condiciones.","simpler":"Dos objetos del mismo volumen pueden tener distinta masa; el más masivo tiene mayor densidad media.","example":"Si una muestra tiene masa 20 g y volumen 10 cm³, su densidad es 2 g/cm³.","why":"La densidad es una razón: aumentar la cantidad de la misma sustancia no cambia esa razón bajo las mismas condiciones.","misconception":"Masa, peso y densidad no son la misma magnitud.","hints":["Divide la masa por el volumen y conserva las unidades.","Dos objetos del mismo volumen pueden tener distinta masa; el más masivo tiene mayor densidad media.","Si una muestra tiene masa 20 g y volumen 10 cm³, su densidad es 2 g/cm³."],"quiz":[{"id":"e-density:q0","question":"20 g en 10 cm³ dan una densidad de…","options":["200 g/cm³","10 g/cm³","2 g/cm³"],"answer":"C","hint":"Divide la masa por el volumen y conserva las unidades.","level":1},{"id":"e-density:q1","question":"La densidad relaciona…","options":["Masa y volumen","Tiempo y velocidad","Longitud y temperatura solamente"],"answer":"A","hint":"Divide la masa por el volumen y conserva las unidades.","level":2},{"id":"e-density:q2","question":"Si duplicas masa y volumen de una muestra homogénea…","options":["La densidad se duplica","La densidad se conserva","La densidad se hace cero"],"answer":"B","hint":"Divide la masa por el volumen y conserva las unidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-force","stage":"eso","subject":"Física y Química","title":"Las fuerzas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Las fuerzas","fuerzas","la fuerza","fuerza y movimiento"],"explanation":"Una fuerza es una interacción que puede cambiar el movimiento o deformar un cuerpo. La fuerza neta es la suma vectorial de las fuerzas. Si es cero, un cuerpo puede estar en reposo o moverse con velocidad constante.","simpler":"No hace falta una fuerza neta para mantener una velocidad constante; sí para cambiarla.","example":"Un libro apoyado en una mesa recibe su peso hacia abajo y la fuerza de la mesa hacia arriba. Si se equilibran, no acelera.","why":"La aceleración responde a la fuerza neta; el estado de movimiento no necesita cambiar si esta es cero.","misconception":"Movimiento y fuerza neta no son equivalentes.","hints":["Dibuja todas las fuerzas y sus direcciones.","No hace falta una fuerza neta para mantener una velocidad constante; sí para cambiarla.","Un libro apoyado en una mesa recibe su peso hacia abajo y la fuerza de la mesa hacia arriba. Si se equilibran, no acelera."],"quiz":[{"id":"e-force:q0","question":"La unidad de fuerza del SI es…","options":["Newton","Julio","Vatio"],"answer":"A","hint":"Dibuja todas las fuerzas y sus direcciones.","level":1},{"id":"e-force:q1","question":"Con fuerza neta cero, un cuerpo puede…","options":["Solo estar parado","Acelerar siempre","Mantener velocidad constante"],"answer":"C","hint":"Dibuja todas las fuerzas y sus direcciones.","level":2},{"id":"e-force:q2","question":"La fuerza neta es…","options":["La mayor fuerza sin más","La suma vectorial de las fuerzas","Siempre el peso"],"answer":"B","hint":"Dibuja todas las fuerzas y sus direcciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-energy","stage":"eso","subject":"Física y Química","title":"La energía","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["La energía","energia","la energia","conservacion de la energia"],"explanation":"La energía permite describir cambios y transferencias en un sistema. Puede almacenarse de distintas formas y transferirse mediante trabajo o calor, entre otros procesos. La energía total se conserva en un sistema aislado; su utilidad para producir ciertos cambios puede disminuir.","simpler":"La energía no desaparece: se transforma o se transfiere. No todas sus formas son igual de aprovechables.","example":"Al frenar una bicicleta, parte de su energía cinética se transforma en energía interna de frenos, ruedas y entorno.","why":"La conservación requiere contabilizar también las transferencias y formas de energía menos evidentes.","misconception":"Conservar energía no significa que toda pueda recuperarse para el mismo uso.","hints":["Define qué incluyes dentro del sistema.","La energía no desaparece: se transforma o se transfiere. No todas sus formas son igual de aprovechables.","Al frenar una bicicleta, parte de su energía cinética se transforma en energía interna de frenos, ruedas y entorno."],"quiz":[{"id":"e-energy:q0","question":"La unidad de energía del SI es…","options":["Newton","Julio","Metro"],"answer":"B","hint":"Define qué incluyes dentro del sistema.","level":1},{"id":"e-energy:q1","question":"Al frenar, parte de la energía cinética…","options":["Se transforma en energía interna","Deja de existir","Se convierte en masa nula"],"answer":"A","hint":"Define qué incluyes dentro del sistema.","level":2},{"id":"e-energy:q2","question":"En un sistema aislado, la energía total…","options":["Aumenta siempre","Desaparece","Se conserva"],"answer":"C","hint":"Define qué incluyes dentro del sistema.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-reaction","stage":"eso","subject":"Física y Química","title":"Reacciones químicas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Reacciones químicas","reacciones quimicas","reaccion quimica"],"explanation":"En una reacción química se transforman unas sustancias, reactivos, en otras, productos. Los átomos se reorganizan y, en las reacciones químicas ordinarias, se conserva el número de átomos de cada elemento. Ajustar una ecuación respeta esa conservación.","simpler":"Los átomos se recombinan: no se inventan ni desaparecen durante una reacción química ordinaria.","example":"2 H₂ + O₂ → 2 H₂O conserva cuatro átomos de hidrógeno y dos de oxígeno a cada lado.","why":"Los coeficientes indican cantidades relativas de partículas sin alterar su composición.","misconception":"Cambiar un subíndice puede cambiar la sustancia; no es el método para ajustar.","hints":["Cuenta cada elemento en ambos miembros.","Los átomos se recombinan: no se inventan ni desaparecen durante una reacción química ordinaria.","2 H₂ + O₂ → 2 H₂O conserva cuatro átomos de hidrógeno y dos de oxígeno a cada lado."],"quiz":[{"id":"e-reaction:q0","question":"Las sustancias iniciales se llaman…","options":["Productos","Disolventes siempre","Reactivos"],"answer":"C","hint":"Cuenta cada elemento en ambos miembros.","level":1},{"id":"e-reaction:q1","question":"En 2 H₂ + O₂ → 2 H₂O hay a cada lado…","options":["4 H y 2 O","2 H y 4 O","1 H y 1 O"],"answer":"A","hint":"Cuenta cada elemento en ambos miembros.","level":2},{"id":"e-reaction:q2","question":"Ajustar cambia principalmente…","options":["Los símbolos de los elementos","Los coeficientes","La identidad de los átomos"],"answer":"B","hint":"Cuenta cada elemento en ambos miembros.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-tectonics","stage":"eso","subject":"Biología y Geología","title":"Tectónica de placas","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Tectónica de placas","tectonica de placas","placas tectonicas"],"explanation":"La litosfera terrestre está dividida en placas que se mueven lentamente sobre regiones más deformables del manto superior. Sus interacciones ayudan a explicar muchos terremotos, volcanes y cordilleras. Las placas no son solo continentes.","simpler":"La superficie rígida forma piezas móviles que incluyen partes continentales y oceánicas.","example":"Cuando dos placas convergen, puede haber subducción o colisión continental, según los tipos de litosfera implicados.","why":"Las rocas del manto pueden deformarse y fluir muy lentamente aunque sean mayoritariamente sólidas.","misconception":"El manto no es un océano global de roca totalmente líquida.","hints":["Relaciona el movimiento relativo con el tipo de límite.","La superficie rígida forma piezas móviles que incluyen partes continentales y oceánicas.","Cuando dos placas convergen, puede haber subducción o colisión continental, según los tipos de litosfera implicados."],"quiz":[{"id":"e-tectonics:q0","question":"Las placas forman parte de la…","options":["Litosfera","Atmósfera","Hidrosfera únicamente"],"answer":"A","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":1},{"id":"e-tectonics:q1","question":"¿Una placa contiene solo continente?","options":["Siempre","Solo en Europa","No necesariamente"],"answer":"C","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":2},{"id":"e-tectonics:q2","question":"Dos placas que se acercan tienen un límite…","options":["Divergente","Convergente","Sin movimiento"],"answer":"B","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-middle-ages","stage":"eso","subject":"Geografía e Historia","title":"La Edad Media","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La Edad Media","edad media","la edad media"],"explanation":"La Edad Media es una periodización de la historia europea. Se sitúa convencionalmente entre la caída del Imperio romano de Occidente en 476 y finales del siglo XV; se usan hitos como 1453 o 1492 según el enfoque. No describe de la misma forma la historia de todo el mundo.","simpler":"Es una etapa histórica de unos mil años en Europa. Las fechas son referencias para organizar procesos, no cambios instantáneos.","example":"476 marca una referencia política; 1492 suele utilizarse en la enseñanza española como cierre convencional. La vida social no cambió toda en un solo día.","why":"Las periodizaciones son herramientas: destacan ciertos procesos y deben explicitar su ámbito geográfico y sus criterios.","misconception":"No presentes 1492 como la única fecha académicamente posible.","hints":["Distingue una convención cronológica de un proceso histórico.","Es una etapa histórica de unos mil años en Europa. Las fechas son referencias para organizar procesos, no cambios instantáneos.","476 marca una referencia política; 1492 suele utilizarse en la enseñanza española como cierre convencional. La vida social no cambió toda en un solo día."],"quiz":[{"id":"e-middle-ages:q0","question":"476 se asocia con…","options":["La Revolución francesa","La caída del Imperio romano de Occidente","La llegada del ferrocarril"],"answer":"B","hint":"Distingue una convención cronológica de un proceso histórico.","level":1},{"id":"e-middle-ages:q1","question":"Las fechas de una periodización son…","options":["Referencias convencionales","Fronteras instantáneas para toda sociedad","Leyes físicas"],"answer":"A","hint":"Distingue una convención cronológica de un proceso histórico.","level":2},{"id":"e-middle-ages:q2","question":"¿La Edad Media europea describe igual toda la historia mundial?","options":["Sí","Solo desde 1492","No"],"answer":"C","hint":"Distingue una convención cronológica de un proceso histórico.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-industrial","stage":"eso","subject":"Geografía e Historia","title":"La Revolución Industrial","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["La Revolución Industrial","revolucion industrial","industrializacion"],"explanation":"La Revolución Industrial fue un proceso de transformación económica y social iniciado en Gran Bretaña en la segunda mitad del siglo XVIII. La mecanización, nuevas fuentes de energía y el sistema fabril modificaron producción, transportes y trabajo. Su difusión fue desigual.","simpler":"Se pasó progresivamente de muchas tareas manuales a una producción mecanizada en fábricas, con importantes cambios sociales.","example":"La máquina de vapor permitió accionar maquinaria y, después, impulsar transportes; no fue el único factor del cambio.","why":"Las innovaciones actúan junto con recursos, instituciones, mercados y cambios sociales.","misconception":"Una sola invención no explica por sí sola toda la industrialización.","hints":["Relaciona tecnología, energía, capital, trabajo y sociedad.","Se pasó progresivamente de muchas tareas manuales a una producción mecanizada en fábricas, con importantes cambios sociales.","La máquina de vapor permitió accionar maquinaria y, después, impulsar transportes; no fue el único factor del cambio."],"quiz":[{"id":"e-industrial:q0","question":"El inicio se sitúa principalmente en…","options":["Gran Bretaña","La Antártida","El Imperio romano"],"answer":"A","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":1},{"id":"e-industrial:q1","question":"Fue un proceso…","options":["Instantáneo","Igual en todos los países","Desigual y prolongado"],"answer":"C","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":2},{"id":"e-industrial:q2","question":"El sistema fabril se relaciona con…","options":["Eliminar toda máquina","Concentrar producción y trabajo en fábricas","Producir solo para autoconsumo"],"answer":"B","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-climate","stage":"eso","subject":"Geografía e Historia","title":"Tiempo y clima","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Tiempo y clima","tiempo y clima","diferencia entre tiempo y clima"],"explanation":"El tiempo atmosférico describe las condiciones de la atmósfera en un lugar y momento. El clima caracteriza sus patrones y variabilidad durante períodos largos, habitualmente de varias décadas. Un día concreto no basta para definir el clima.","simpler":"Tiempo es lo que ocurre ahora; clima es cómo suelen variar esas condiciones a lo largo de muchos años.","example":"«Hoy llueve» describe el tiempo. «Los veranos suelen ser secos» describe un rasgo climático de un lugar.","why":"El clima se describe estadísticamente; los días particulares pueden apartarse de sus valores habituales.","misconception":"No confundas la variabilidad diaria con una tendencia a largo plazo.","hints":["Pregunta si el dato se refiere a un momento o a una serie prolongada.","Tiempo es lo que ocurre ahora; clima es cómo suelen variar esas condiciones a lo largo de muchos años.","«Hoy llueve» describe el tiempo. «Los veranos suelen ser secos» describe un rasgo climático de un lugar."],"quiz":[{"id":"e-climate:q0","question":"«Hoy hay 15 °C» describe…","options":["El clima completo","El tiempo","La latitud"],"answer":"B","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":1},{"id":"e-climate:q1","question":"Para estudiar el clima necesitamos…","options":["Series de muchos años","Solo el día más cálido","Una fotografía"],"answer":"A","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":2},{"id":"e-climate:q2","question":"Un día frío…","options":["Demuestra por sí solo enfriamiento global","Define todo un clima","No basta para concluir una tendencia climática"],"answer":"C","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-sources","stage":"eso","subject":"Geografía e Historia","title":"Fuentes históricas","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Fuentes históricas","fuentes historicas","fuentes primarias y secundarias"],"explanation":"Una fuente histórica aporta información para investigar el pasado. Una fuente primaria procede del contexto estudiado; una secundaria lo analiza posteriormente. Hay que valorar autoría, fecha, finalidad, contexto y límites, y contrastar fuentes.","simpler":"Una carta de la época y un estudio actual pueden informar del pasado de formas diferentes.","example":"Una carta de 1910 puede ser primaria para estudiar su época; un libro de un historiador que la analiza es una fuente secundaria.","why":"Cada fuente refleja una perspectiva; contrastarlas ayuda a justificar interpretaciones con pruebas.","misconception":"Primaria no significa automáticamente verdadera, completa o neutral.","hints":["Pregunta quién produjo la fuente y con qué propósito.","Una carta de la época y un estudio actual pueden informar del pasado de formas diferentes.","Una carta de 1910 puede ser primaria para estudiar su época; un libro de un historiador que la analiza es una fuente secundaria."],"quiz":[{"id":"e-sources:q0","question":"Una carta de la época estudiada suele ser…","options":["Una fuente primaria","Siempre una mentira","Una fuente secundaria por definición"],"answer":"A","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":1},{"id":"e-sources:q1","question":"¿Qué conviene hacer con una fuente?","options":["Creerla sin contexto","Ignorar quién la hizo","Analizarla y contrastarla"],"answer":"C","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":2},{"id":"e-sources:q2","question":"Una fuente primaria…","options":["Siempre es neutral","También puede tener sesgos","No necesita fecha"],"answer":"B","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-text","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Coherencia y cohesión","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Coherencia y cohesión","coherencia y cohesion","coherencia textual","cohesion textual"],"explanation":"La coherencia hace que las ideas formen un sentido global y no se contradigan sin explicación. La cohesión relaciona las partes mediante conectores, referencias, elipsis y otros recursos. Un texto puede tener conectores y aun así ser incoherente.","simpler":"Coherencia es que las ideas encajen; cohesión es cómo enlazas sus partes.","example":"«Estudié el tema. Por eso pude explicarlo» conecta una causa con una consecuencia. El conector debe corresponder a la relación real.","why":"Los mecanismos lingüísticos deben expresar relaciones que tengan sentido, no sustituirlas.","misconception":"Añadir conectores no repara por sí solo una contradicción.","hints":["Comprueba primero la relación entre ideas y luego el recurso que las une.","Coherencia es que las ideas encajen; cohesión es cómo enlazas sus partes.","«Estudié el tema. Por eso pude explicarlo» conecta una causa con una consecuencia. El conector debe corresponder a la relación real."],"quiz":[{"id":"e-text:q0","question":"Los conectores contribuyen principalmente a…","options":["La ortografía de todas las palabras","La cohesión","El tamaño del texto"],"answer":"B","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":1},{"id":"e-text:q1","question":"La coherencia exige…","options":["Sentido global entre las ideas","Muchos conectores sin criterio","Solo frases largas"],"answer":"A","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":2},{"id":"e-text:q2","question":"Un texto con conectores puede ser…","options":["Siempre perfecto","Siempre argumentativo","Incoherente"],"answer":"C","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-metaphor","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Metáfora y comparación","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Metáfora y comparación","metafora y comparacion","metafora","simil"],"explanation":"Una metáfora presenta una realidad en términos de otra por una relación de semejanza, sin formular necesariamente una comparación explícita. Un símil hace explícita esa comparación, a menudo con «como». Hay que interpretarlos en contexto.","simpler":"«Tus ojos son estrellas» es una metáfora. «Tus ojos brillan como estrellas» es una comparación explícita.","example":"La imagen de estrellas sugiere brillo; no afirma que haya astros físicamente en los ojos.","why":"La semejanza seleccionada crea un significado que el contexto ayuda a precisar.","misconception":"El lenguaje figurado no se interpreta siempre como una afirmación literal.","hints":["Busca qué cualidad relaciona las dos realidades.","«Tus ojos son estrellas» es una metáfora. «Tus ojos brillan como estrellas» es una comparación explícita.","La imagen de estrellas sugiere brillo; no afirma que haya astros físicamente en los ojos."],"quiz":[{"id":"e-metaphor:q0","question":"«Corre como el viento» es un…","options":["Símil","Artículo","Número"],"answer":"A","hint":"Busca qué cualidad relaciona las dos realidades.","level":1},{"id":"e-metaphor:q1","question":"Una metáfora debe interpretarse…","options":["Siempre literalmente","Sin leer el texto","En contexto"],"answer":"C","hint":"Busca qué cualidad relaciona las dos realidades.","level":2},{"id":"e-metaphor:q2","question":"«El tiempo es oro» sugiere que el tiempo…","options":["Es un metal","Es valioso","Pesa igual que el oro"],"answer":"B","hint":"Busca qué cualidad relaciona las dos realidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-present","stage":"eso","subject":"Lengua Extranjera: Inglés","title":"Present simple","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Present simple","present simple","presente simple en ingles"],"explanation":"El present simple se utiliza, entre otros usos, para hábitos y hechos generales. En afirmativa, he, she e it suelen añadir -s o -es al verbo. En preguntas y negativas con verbos léxicos usamos do o does; el verbo principal vuelve a la forma base.","simpler":"«She plays» lleva -s, pero «Does she play?» no la lleva en play.","example":"«He reads every day». Pregunta: «Does he read every day?». Negativa: «He does not read every day».","why":"El auxiliar lleva la marca gramatical de persona; el verbo principal se mantiene en su forma base.","misconception":"No pongas la marca de tercera persona a la vez en does y en el verbo principal.","hints":["Mira si does ya expresa la tercera persona.","«She plays» lleva -s, pero «Does she play?» no la lleva en play.","«He reads every day». Pregunta: «Does he read every day?». Negativa: «He does not read every day»."],"quiz":[{"id":"e-present:q0","question":"Completa: She ___ tennis.","options":["Play","Playing","Plays"],"answer":"C","hint":"Mira si does ya expresa la tercera persona.","level":1},{"id":"e-present:q1","question":"¿Qué pregunta es correcta?","options":["Does he work?","Does he works?","Do he works?"],"answer":"A","hint":"Mira si does ya expresa la tercera persona.","level":2},{"id":"e-present:q2","question":"En «She does not eat», eat está en…","options":["Pasado","Forma base","Participio"],"answer":"B","hint":"Mira si does ya expresa la tercera persona.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-algorithm","stage":"eso","subject":"Tecnología y Digitalización","title":"Los algoritmos","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Los algoritmos","algoritmos","algoritmo","pensamiento computacional"],"explanation":"Un algoritmo es una secuencia precisa de pasos para resolver una tarea o problema. Puede incluir decisiones y repeticiones. Debe indicar qué datos necesita y qué resultado se espera, y debe comprobarse con casos diferentes.","simpler":"Escribe pasos claros que otra persona o una máquina pueda seguir sin adivinar.","example":"Para decidir si un entero es par: calcula el resto de dividirlo entre 2; si es 0, es par; en caso contrario, es impar.","why":"Los casos límite revelan errores que no aparecen con ejemplos habituales.","misconception":"Que un programa funcione una vez no demuestra que sea correcto para todos los casos.","hints":["Define entrada, pasos y salida.","Escribe pasos claros que otra persona o una máquina pueda seguir sin adivinar.","Para decidir si un entero es par: calcula el resto de dividirlo entre 2; si es 0, es par; en caso contrario, es impar."],"quiz":[{"id":"e-algorithm:q0","question":"Un algoritmo necesita pasos…","options":["Precisos","Ambiguos siempre","Aleatorios sin finalidad"],"answer":"A","hint":"Define entrada, pasos y salida.","level":1},{"id":"e-algorithm:q1","question":"Una condición permite…","options":["Solo repetir texto","Guardar cualquier contraseña","Elegir entre acciones"],"answer":"C","hint":"Define entrada, pasos y salida.","level":2},{"id":"e-algorithm:q2","question":"Probar varios casos ayuda a…","options":["Garantizar perfección absoluta","Encontrar errores y límites","Eliminar los datos"],"answer":"B","hint":"Define entrada, pasos y salida.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-digital","stage":"eso","subject":"Tecnología y Digitalización","title":"Privacidad digital","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Privacidad digital","privacidad digital","datos personales","seguridad digital"],"explanation":"La privacidad digital consiste en controlar cómo se usan y comparten los datos personales. Antes de publicar, piensa quién podrá acceder y para qué. Usa contraseñas robustas y diferentes y pide ayuda a un adulto de confianza ante solicitudes sospechosas.","simpler":"No hace falta compartir dirección, contraseñas o ubicación exacta para aprender en línea.","example":"Un mensaje que pide tu contraseña para darte un premio es una señal de alerta. No la envíes; verifica por un canal de confianza.","why":"La apariencia se puede copiar; la verificación debe basarse en el origen y no solo en el diseño.","misconception":"Un logotipo conocido no prueba que un mensaje sea auténtico.","hints":["Comparte solo los datos necesarios y verifica la identidad por otra vía.","No hace falta compartir dirección, contraseñas o ubicación exacta para aprender en línea.","Un mensaje que pide tu contraseña para darte un premio es una señal de alerta. No la envíes; verifica por un canal de confianza."],"quiz":[{"id":"e-digital:q0","question":"¿Qué dato no debes enviar por chat a un desconocido?","options":["El resultado de una suma","Tu contraseña","El título de un libro"],"answer":"B","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":1},{"id":"e-digital:q1","question":"Ante un mensaje sospechoso conviene…","options":["Parar y verificar con ayuda","Responder deprisa","Abrir todos los enlaces"],"answer":"A","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":2},{"id":"e-digital:q2","question":"Una contraseña para todas las cuentas…","options":["Siempre es lo más seguro","Nunca puede filtrarse","Aumenta el riesgo si se filtra"],"answer":"C","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-rhythm","stage":"eso","subject":"Música","title":"Pulso y ritmo","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Pulso y ritmo","pulso y ritmo","ritmo musical","pulso musical"],"explanation":"El pulso es la referencia regular que puede acompañar la música. El ritmo organiza duraciones, acentos y silencios sobre esa referencia. Pueden aparecer varios sonidos dentro de un pulso o mantenerse un sonido durante varios.","simpler":"Marca un paso regular: ese es el pulso. Cambia las palmadas encima: cambias el ritmo.","example":"Mantén cuatro golpes regulares con el pie y da dos palmadas suaves en uno de ellos. El pulso sigue mientras varía el ritmo.","why":"La referencia periódica ayuda a percibir cómo se distribuyen los acontecimientos sonoros.","misconception":"Pulso y ritmo no son sinónimos.","hints":["Mantén una referencia regular mientras escuchas las duraciones.","Marca un paso regular: ese es el pulso. Cambia las palmadas encima: cambias el ritmo.","Mantén cuatro golpes regulares con el pie y da dos palmadas suaves en uno de ellos. El pulso sigue mientras varía el ritmo."],"quiz":[{"id":"e-rhythm:q0","question":"El pulso suele ser una referencia…","options":["Regular","Siempre silenciosa","Sin relación con el tiempo"],"answer":"A","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":1},{"id":"e-rhythm:q1","question":"El ritmo organiza…","options":["Solo la intensidad","Solo la altura","Duraciones, acentos y silencios"],"answer":"C","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":2},{"id":"e-rhythm:q2","question":"Dentro de un pulso puede haber…","options":["Siempre exactamente una nota","Varios sonidos","Ninguna subdivisión posible"],"answer":"B","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-limits","stage":"bachillerato","subject":"Matemáticas","title":"Límites de funciones","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Límites de funciones","limites","limites de funciones","limite de una funcion"],"explanation":"El límite describe a qué valor se aproxima una función cuando la variable se aproxima a un punto o crece sin cota. Puede existir aunque la función no esté definida en el punto. Sustituir directamente funciona en muchos casos de continuidad, pero no resuelve todas las indeterminaciones.","simpler":"No preguntamos necesariamente cuánto vale la función en el punto, sino a qué valor se acercan sus resultados.","example":"Para x distinto de 1, (x² − 1)/(x − 1) = x + 1. Al acercarse x a 1, el límite es 2, aunque la expresión original no esté definida en 1.","why":"El límite depende del comportamiento próximo al punto, no necesariamente de su valor puntual.","misconception":"0/0 no es un valor numérico ni demuestra por sí solo que no exista límite.","hints":["Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","No preguntamos necesariamente cuánto vale la función en el punto, sino a qué valor se acercan sus resultados.","Para x distinto de 1, (x² − 1)/(x − 1) = x + 1. Al acercarse x a 1, el límite es 2, aunque la expresión original no esté definida en 1."],"quiz":[{"id":"b-limits:q0","question":"El límite al acercarse x a 1 de (x²−1)/(x−1) es…","options":["1","2","No existe necesariamente"],"answer":"B","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":1},{"id":"b-limits:q1","question":"¿Puede existir un límite donde la función no esté definida?","options":["Sí","Nunca","Solo si vale cero"],"answer":"A","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":2},{"id":"b-limits:q2","question":"Obtener 0/0 por sustitución indica…","options":["Que el límite es cero","Que el límite es uno","Una indeterminación que exige análisis"],"answer":"C","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-derivative","stage":"bachillerato","subject":"Matemáticas","title":"La derivada","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La derivada","derivadas","derivada","la derivada"],"explanation":"La derivada mide una tasa de variación instantánea. Geométricamente, cuando existe, es la pendiente de la recta tangente a la gráfica. Se define mediante el límite del cociente incremental; no es simplemente una división entre coordenadas.","simpler":"Compara cambios cada vez más pequeños para describir cómo cambia la función justo en un punto.","example":"Si f(x) = x², f'(x) = 2x. En x = 3, la pendiente de la tangente es 6.","why":"La definición exige un límite de pendientes secantes; si no converge de forma compatible, no hay derivada en ese punto.","misconception":"Una función puede ser continua y no ser derivable en algún punto.","hints":["Distingue la función derivada del valor de la derivada en un punto.","Compara cambios cada vez más pequeños para describir cómo cambia la función justo en un punto.","Si f(x) = x², f'(x) = 2x. En x = 3, la pendiente de la tangente es 6."],"quiz":[{"id":"b-derivative:q0","question":"La derivada de x² es…","options":["x","x²/2","2x"],"answer":"C","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":1},{"id":"b-derivative:q1","question":"Para f(x) = x², f'(3) es…","options":["6","9","3"],"answer":"A","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":2},{"id":"b-derivative:q2","question":"Una derivada expresa una tasa de variación…","options":["Solo media en un intervalo fijo","Instantánea","Siempre positiva"],"answer":"B","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-integral","stage":"bachillerato","subject":"Matemáticas","title":"La integral definida","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["La integral definida","integrales","integral definida","integracion"],"explanation":"La integral definida acumula contribuciones de una función en un intervalo. Puede interpretarse como área con signo: las zonas bajo el eje contribuyen negativamente. Si F es una primitiva de una función continua f, la integral entre a y b es F(b) − F(a).","simpler":"Sumamos aportaciones muy pequeñas a lo largo de un intervalo. El signo importa.","example":"La integral de 2x entre 0 y 2 es [x²] entre 0 y 2: 4 − 0 = 4.","why":"La integral suma valores con signo; el área geométrica requiere contabilizar las regiones como cantidades no negativas.","misconception":"Una integral definida negativa no es un error por el mero hecho de ser negativa.","hints":["Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","Sumamos aportaciones muy pequeñas a lo largo de un intervalo. El signo importa.","La integral de 2x entre 0 y 2 es [x²] entre 0 y 2: 4 − 0 = 4."],"quiz":[{"id":"b-integral:q0","question":"Una primitiva de 2x es…","options":["x²","2","x"],"answer":"A","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":1},{"id":"b-integral:q1","question":"La integral de 2x entre 0 y 2 vale…","options":["2","8","4"],"answer":"C","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":2},{"id":"b-integral:q2","question":"El área geométrica y el área con signo…","options":["Son siempre iguales","Pueden ser distintas","Nunca están relacionadas"],"answer":"B","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-matrices","stage":"bachillerato","subject":"Matemáticas","title":"Las matrices","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Las matrices","matrices","matriz"],"explanation":"Una matriz organiza números en filas y columnas. Su dimensión se expresa como número de filas por número de columnas. Para sumar matrices deben tener la misma dimensión. Para multiplicar A por B, las columnas de A deben coincidir con las filas de B.","simpler":"Identifica primero filas y columnas. Después comprueba si la operación está definida.","example":"Una matriz de 2 × 3 puede multiplicarse por una de 3 × 4; el resultado tiene dimensión 2 × 4.","why":"Cada entrada del producto combina una fila de la primera matriz con una columna de la segunda.","misconception":"La multiplicación de matrices no es conmutativa en general.","hints":["Comprueba las dimensiones antes de calcular.","Identifica primero filas y columnas. Después comprueba si la operación está definida.","Una matriz de 2 × 3 puede multiplicarse por una de 3 × 4; el resultado tiene dimensión 2 × 4."],"quiz":[{"id":"b-matrices:q0","question":"Una matriz de 2 × 3 tiene…","options":["3 filas y 2 columnas","2 filas y 3 columnas","6 filas"],"answer":"B","hint":"Comprueba las dimensiones antes de calcular.","level":1},{"id":"b-matrices:q1","question":"El producto (2 × 3) por (3 × 4) da dimensión…","options":["2 × 4","3 × 3","4 × 2"],"answer":"A","hint":"Comprueba las dimensiones antes de calcular.","level":2},{"id":"b-matrices:q2","question":"En general, AB y BA…","options":["Son siempre iguales","Siempre existen ambos","Pueden no coincidir o no estar ambos definidos"],"answer":"C","hint":"Comprueba las dimensiones antes de calcular.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-newton","stage":"bachillerato","subject":"Física","title":"Segunda ley de Newton","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Segunda ley de Newton","segunda ley de newton","fuerza masa y aceleracion"],"explanation":"En un sistema de referencia inercial y para masa constante, la fuerza neta es igual a la masa por la aceleración: ΣF = ma. Es una relación vectorial. Debemos sumar todas las fuerzas y distinguirlas de la velocidad.","simpler":"La fuerza neta determina cómo cambia la velocidad, no cuál es la velocidad en ese instante.","example":"Una fuerza neta de 10 N sobre una masa de 2 kg produce una aceleración de 5 m/s² en la dirección de esa fuerza.","why":"La aceleración es el cambio de velocidad; un movimiento uniforme puede tener fuerza neta nula.","misconception":"La presencia de movimiento no implica una fuerza neta en su dirección.","hints":["Elige el sistema, representa las fuerzas y suma por componentes.","La fuerza neta determina cómo cambia la velocidad, no cuál es la velocidad en ese instante.","Una fuerza neta de 10 N sobre una masa de 2 kg produce una aceleración de 5 m/s² en la dirección de esa fuerza."],"quiz":[{"id":"b-newton:q0","question":"Con F neta = 12 N y m = 3 kg, la aceleración es…","options":["36 m/s²","9 m/s²","4 m/s²"],"answer":"C","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":1},{"id":"b-newton:q1","question":"La ley usa…","options":["La fuerza neta","Solo la mayor fuerza","La velocidad en lugar de fuerza"],"answer":"A","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":2},{"id":"b-newton:q2","question":"Fuerza y aceleración son magnitudes…","options":["Siempre escalares","Vectoriales","Sin unidades"],"answer":"B","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-ohm","stage":"bachillerato","subject":"Física","title":"Ley de Ohm","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Ley de Ohm","ley de ohm","resistencia electrica"],"explanation":"Para un elemento óhmico en condiciones constantes, tensión, intensidad y resistencia se relacionan mediante V = IR. Voltios, amperios y ohmios son sus unidades respectivas. La relación no describe todos los dispositivos ni todas las condiciones.","simpler":"En una resistencia óhmica, a mayor tensión corresponde mayor corriente si la resistencia no cambia.","example":"Con una resistencia ideal de 6 Ω y una tensión de 12 V, la intensidad es 2 A. Trabajamos con el modelo; no hagas conexiones a la red eléctrica.","why":"La resistencia expresa la proporcionalidad entre tensión y corriente para el comportamiento óhmico considerado.","misconception":"Tensión e intensidad no son la misma magnitud.","hints":["Despeja la incógnita antes de sustituir.","En una resistencia óhmica, a mayor tensión corresponde mayor corriente si la resistencia no cambia.","Con una resistencia ideal de 6 Ω y una tensión de 12 V, la intensidad es 2 A. Trabajamos con el modelo; no hagas conexiones a la red eléctrica."],"quiz":[{"id":"b-ohm:q0","question":"Con V = 12 V y R = 6 Ω, I es…","options":["2 A","72 A","6 A"],"answer":"A","hint":"Despeja la incógnita antes de sustituir.","level":1},{"id":"b-ohm:q1","question":"La unidad de resistencia es…","options":["Amperio","Voltio","Ohmio"],"answer":"C","hint":"Despeja la incógnita antes de sustituir.","level":2},{"id":"b-ohm:q2","question":"La ley se aplica en su forma simple a…","options":["Todo dispositivo sin condiciones","Elementos óhmicos bajo condiciones adecuadas","Solo corrientes nulas"],"answer":"B","hint":"Despeja la incógnita antes de sustituir.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-mole","stage":"bachillerato","subject":"Química","title":"El mol","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["El mol","mol","el mol","cantidad de sustancia"],"explanation":"El mol es la unidad del SI de cantidad de sustancia. Un mol contiene exactamente 6,02214076 × 10²³ entidades elementales especificadas. Para una sustancia dada, n = m/M relaciona cantidad, masa y masa molar. Hay que indicar si contamos átomos, moléculas u otras entidades.","simpler":"El mol funciona como una unidad de recuento enorme; no es una masa fija para todas las sustancias.","example":"Si usamos M = 18 g/mol para un ejercicio aproximado con agua, 36 g corresponden a 2 mol de moléculas de agua.","why":"Las partículas tienen masas diferentes; el mismo número de entidades puede corresponder a masas distintas.","misconception":"El número de Avogadro no significa que un mol pese siempre un gramo.","hints":["Especifica las entidades y revisa las unidades de masa molar.","El mol funciona como una unidad de recuento enorme; no es una masa fija para todas las sustancias.","Si usamos M = 18 g/mol para un ejercicio aproximado con agua, 36 g corresponden a 2 mol de moléculas de agua."],"quiz":[{"id":"b-mole:q0","question":"Con m = 36 g y M = 18 g/mol, n es…","options":["18 mol","2 mol","648 mol"],"answer":"B","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":1},{"id":"b-mole:q1","question":"¿Un mol tiene la misma masa en todas las sustancias?","options":["No","Sí","Solo si son gases"],"answer":"A","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":2},{"id":"b-mole:q2","question":"La expresión n = m/M requiere…","options":["Sumar unidades sin mirar","Confundir masa y cantidad","Usar unidades compatibles"],"answer":"C","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-ph","stage":"bachillerato","subject":"Química","title":"El pH","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["El pH","ph","el ph","acidez y ph"],"explanation":"El pH se define mediante el logaritmo negativo de la actividad del ion hidrógeno. En disoluciones acuosas suficientemente diluidas se aproxima como −log₁₀[H₃O⁺], con la convención de concentración adecuada. La neutralidad depende de la temperatura; a 25 °C se sitúa aproximadamente en pH 7.","simpler":"La escala es logarítmica: cambiar una unidad representa un factor diez en la actividad correspondiente.","example":"En la aproximación diluida, [H₃O⁺] = 10⁻³ mol/L da pH ≈ 3. No manipules sustancias desconocidas para probarlo.","why":"El producto iónico del agua varía con la temperatura y la actividad no coincide siempre con la concentración.","misconception":"La escala 0–14 no es un límite universal del pH en todas las disoluciones.","hints":["Recuerda que es una escala logarítmica y especifica las condiciones.","La escala es logarítmica: cambiar una unidad representa un factor diez en la actividad correspondiente.","En la aproximación diluida, [H₃O⁺] = 10⁻³ mol/L da pH ≈ 3. No manipules sustancias desconocidas para probarlo."],"quiz":[{"id":"b-ph:q0","question":"Con [H₃O⁺] ≈ 10⁻³ mol/L, el pH aproximado es…","options":["−3","10","3"],"answer":"C","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":1},{"id":"b-ph:q1","question":"Una unidad de pH corresponde a un factor aproximado de…","options":["10","2","1000"],"answer":"A","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":2},{"id":"b-ph:q2","question":"La neutralidad a pH 7 se asocia aproximadamente a…","options":["Cualquier temperatura sin excepción","25 °C","La ausencia de agua"],"answer":"B","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-dna","stage":"bachillerato","subject":"Biología","title":"ADN y expresión génica","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["ADN y expresión génica","adn","expresion genica","adn y arn"],"explanation":"El ADN almacena información genética en su secuencia de nucleótidos. En la expresión de muchos genes, se transcribe ARN y, para genes codificantes, se traduce la secuencia del ARN mensajero a una proteína. No todos los genes codifican proteínas.","simpler":"Transcripción: del ADN al ARN. Traducción: del ARN mensajero a una secuencia de aminoácidos.","example":"Un ribosoma lee codones del ARN mensajero durante la traducción. El ADN no se convierte físicamente en proteína.","why":"La información se expresa mediante procesos moleculares distintos; no implica que una molécula se transforme directamente en otra de naturaleza diferente.","misconception":"Los aminoácidos no son las unidades básicas del ADN.","hints":["Distingue copia de información, molécula original y producto.","Transcripción: del ADN al ARN. Traducción: del ARN mensajero a una secuencia de aminoácidos.","Un ribosoma lee codones del ARN mensajero durante la traducción. El ADN no se convierte físicamente en proteína."],"quiz":[{"id":"b-dna:q0","question":"La transcripción produce…","options":["ARN","Siempre glucosa","Una membrana"],"answer":"A","hint":"Distingue copia de información, molécula original y producto.","level":1},{"id":"b-dna:q1","question":"La traducción ocurre en…","options":["Los cromosomas como órgano","El aparato circulatorio","Los ribosomas"],"answer":"C","hint":"Distingue copia de información, molécula original y producto.","level":2},{"id":"b-dna:q2","question":"¿Todos los genes codifican proteínas?","options":["Sí","No","Solo en bacterias"],"answer":"B","hint":"Distingue copia de información, molécula original y producto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-meiosis","stage":"bachillerato","subject":"Biología","title":"La meiosis","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La meiosis","meiosis","la meiosis"],"explanation":"La meiosis es una división celular especializada que reduce el número de juegos cromosómicos. Comprende dos divisiones tras una replicación de ADN. La recombinación y la distribución de cromosomas contribuyen a la variabilidad genética.","simpler":"Primero se replica el ADN y después ocurren dos divisiones. El resultado reduce la dotación cromosómica.","example":"En un modelo diploide con 2n = 6, las células finales tienen n = 3 cromosomas, si el proceso transcurre normalmente.","why":"La reducción permite que la fecundación restablezca la dotación y la recombinación reorganiza variantes heredadas.","misconception":"Reducir dotación cromosómica no equivale a perder genes de forma arbitraria.","hints":["Distingue cromosomas homólogos de cromátidas hermanas.","Primero se replica el ADN y después ocurren dos divisiones. El resultado reduce la dotación cromosómica.","En un modelo diploide con 2n = 6, las células finales tienen n = 3 cromosomas, si el proceso transcurre normalmente."],"quiz":[{"id":"b-meiosis:q0","question":"Tras meiosis de una célula con 2n = 6, la dotación final es…","options":["6n","n = 3","2n = 12"],"answer":"B","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":1},{"id":"b-meiosis:q1","question":"Antes de las dos divisiones hay…","options":["Una replicación de ADN","Dos replicaciones obligatorias","Ninguna replicación"],"answer":"A","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":2},{"id":"b-meiosis:q2","question":"La recombinación contribuye a…","options":["Eliminar toda variación","Duplicar siempre la especie","La variabilidad genética"],"answer":"C","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-argument","stage":"bachillerato","subject":"Lengua Castellana y Literatura","title":"El texto argumentativo","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["El texto argumentativo","texto argumentativo","argumentacion","argumentar"],"explanation":"Argumentar consiste en sostener una tesis mediante razones y, cuando corresponde, pruebas. Hay que distinguir afirmaciones, evidencia y supuestos; considerar objeciones pertinentes y responderlas sin deformar la posición contraria.","simpler":"No basta decir qué opinas: explica por qué y qué apoya tus razones.","example":"Tesis: conviene contrastar fuentes antes de compartir una noticia. Razón: así podemos detectar errores. Evidencia: comparar autoría, fecha y documentos originales en un caso concreto.","why":"La calidad de un argumento depende del respaldo y de la relación entre premisas y conclusión, no solo de su fuerza retórica.","misconception":"Persuadir y demostrar no son exactamente lo mismo.","hints":["Separa tesis, razones, pruebas y posibles objeciones.","No basta decir qué opinas: explica por qué y qué apoya tus razones.","Tesis: conviene contrastar fuentes antes de compartir una noticia. Razón: así podemos detectar errores. Evidencia: comparar autoría, fecha y documentos originales en un caso concreto."],"quiz":[{"id":"b-argument:q0","question":"La tesis es…","options":["La posición que se defiende","Cualquier ejemplo aislado","El título siempre"],"answer":"A","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":1},{"id":"b-argument:q1","question":"Una objeción debe…","options":["Ocultarse siempre","Ridiculizarse","Analizarse con honestidad"],"answer":"C","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":2},{"id":"b-argument:q2","question":"Una afirmación repetida muchas veces…","options":["Se convierte en prueba","No es por eso verdadera","Deja de necesitar justificación"],"answer":"B","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-deduction","stage":"bachillerato","subject":"Filosofía","title":"Deducción e inducción","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Deducción e inducción","deduccion e induccion","razonamiento deductivo","razonamiento inductivo"],"explanation":"Un argumento deductivo válido no permite premisas verdaderas y conclusión falsa al mismo tiempo. La inducción apoya una conclusión ampliativa con grados de fuerza, pero no la garantiza del mismo modo. Validez y verdad de las premisas son cuestiones diferentes.","simpler":"En deducción válida, la conclusión se sigue necesariamente si las premisas son verdaderas. En inducción hay apoyo, no garantía lógica absoluta.","example":"«Todos los mamíferos son vertebrados; las ballenas son mamíferos; luego las ballenas son vertebrados» tiene forma deductiva válida.","why":"La forma lógica garantiza una relación condicional, no certifica por sí sola los hechos enunciados.","misconception":"Un argumento válido no es automáticamente un argumento con premisas verdaderas.","hints":["Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","En deducción válida, la conclusión se sigue necesariamente si las premisas son verdaderas. En inducción hay apoyo, no garantía lógica absoluta.","«Todos los mamíferos son vertebrados; las ballenas son mamíferos; luego las ballenas son vertebrados» tiene forma deductiva válida."],"quiz":[{"id":"b-deduction:q0","question":"La validez deductiva depende de…","options":["Que guste la conclusión","La relación lógica entre premisas y conclusión","La longitud del texto"],"answer":"B","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":1},{"id":"b-deduction:q1","question":"¿Un argumento válido puede tener una premisa falsa?","options":["Sí","No","Solo si es inductivo"],"answer":"A","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":2},{"id":"b-deduction:q2","question":"Una inducción fuerte proporciona…","options":["Certeza lógica absoluta siempre","Una definición sin datos","Apoyo a una conclusión ampliativa"],"answer":"C","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-1812","stage":"bachillerato","subject":"Historia de España","title":"La Constitución de 1812","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["La Constitución de 1812","constitucion de 1812","la pepa","cortes de cadiz"],"explanation":"La Constitución de 1812 fue aprobada por las Cortes de Cádiz durante la Guerra de la Independencia. Defendió principios como la soberanía nacional y la división de poderes, dentro de una monarquía constitucional. Su liberalismo coexistía con límites y exclusiones propios del contexto.","simpler":"Fue un texto clave del primer liberalismo español, no una democracia idéntica a las actuales.","example":"Su aprobación el 19 de marzo explica el sobrenombre «la Pepa». Para analizarla conviene comparar principios, instituciones y límites de participación.","why":"El análisis histórico combina avances respecto al orden anterior con las limitaciones efectivas del nuevo sistema.","misconception":"No proyectes automáticamente categorías actuales sobre instituciones del siglo XIX.","hints":["Sitúa el documento en su contexto bélico y político.","Fue un texto clave del primer liberalismo español, no una democracia idéntica a las actuales.","Su aprobación el 19 de marzo explica el sobrenombre «la Pepa». Para analizarla conviene comparar principios, instituciones y límites de participación."],"quiz":[{"id":"b-1812:q0","question":"La Constitución se aprobó en…","options":["Cádiz","Barcelona","Lisboa"],"answer":"A","hint":"Sitúa el documento en su contexto bélico y político.","level":1},{"id":"b-1812:q1","question":"La soberanía nacional atribuye la soberanía a…","options":["Un propietario individual","Un ejército extranjero","La nación"],"answer":"C","hint":"Sitúa el documento en su contexto bélico y político.","level":2},{"id":"b-1812:q2","question":"¿Equivale sin matices a una democracia actual?","options":["Sí","No","Solo por su apodo"],"answer":"B","hint":"Sitúa el documento en su contexto bélico y político.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-opportunity","stage":"bachillerato","subject":"Economía","title":"Coste de oportunidad","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Coste de oportunidad","coste de oportunidad","escasez economica"],"explanation":"El coste de oportunidad es el valor de la mejor alternativa a la que renuncias cuando eliges. Aparece porque tiempo y recursos son limitados. No equivale a sumar todas las alternativas ni se reduce siempre a un pago monetario.","simpler":"Elegir una opción significa dejar otra posible sin realizar. Importa la mejor alternativa descartada.","example":"Si dedicas una hora a una actividad y tu mejor alternativa era estudiar, el coste de oportunidad incluye el valor de ese estudio no realizado.","why":"Una decisión utiliza recursos que no pueden destinarse simultáneamente a su mejor uso alternativo.","misconception":"No todas las renuncias se suman para calcular el coste de oportunidad.","hints":["Identifica alternativas reales y cuál era la mejor descartada.","Elegir una opción significa dejar otra posible sin realizar. Importa la mejor alternativa descartada.","Si dedicas una hora a una actividad y tu mejor alternativa era estudiar, el coste de oportunidad incluye el valor de ese estudio no realizado."],"quiz":[{"id":"b-opportunity:q0","question":"El coste de oportunidad se refiere a…","options":["Todas las opciones sumadas","La mejor alternativa descartada","Solo el precio pagado"],"answer":"B","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":1},{"id":"b-opportunity:q1","question":"Puede existir aunque no haya dinero…","options":["Sí","Nunca","Solo en empresas"],"answer":"A","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":2},{"id":"b-opportunity:q2","question":"Se relaciona con…","options":["Recursos ilimitados","No tomar decisiones","La escasez y la elección"],"answer":"C","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-passive","stage":"bachillerato","subject":"Lengua Extranjera: Inglés","title":"La voz pasiva en inglés","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La voz pasiva en inglés","voz pasiva en ingles","passive voice","pasiva inglesa"],"explanation":"La pasiva inglesa suele formarse con be en el tiempo correspondiente y el participio pasado del verbo principal. Destaca la entidad afectada por la acción. El complemento con by puede indicar el agente cuando resulta relevante.","simpler":"Mantén el tiempo verbal en be y utiliza el participio del verbo principal.","example":"«They built the bridge» puede transformarse en «The bridge was built». El sujeto cambia de función, pero debemos conservar el sentido y el tiempo.","why":"La pasiva reorganiza la información de la oración; la elección depende de qué queremos destacar.","misconception":"No todos los participios se forman añadiendo -ed.","hints":["Localiza el objeto de la activa y conserva el tiempo verbal.","Mantén el tiempo verbal en be y utiliza el participio del verbo principal.","«They built the bridge» puede transformarse en «The bridge was built». El sujeto cambia de función, pero debemos conservar el sentido y el tiempo."],"quiz":[{"id":"b-passive:q0","question":"La pasiva de «They built the bridge» es…","options":["The bridge builds","The bridge is build","The bridge was built"],"answer":"C","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":1},{"id":"b-passive:q1","question":"La estructura básica incluye…","options":["Be + participio pasado","Have + infinitivo siempre","Do + gerundio"],"answer":"A","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":2},{"id":"b-passive:q2","question":"El agente con by…","options":["Es obligatorio en todas las pasivas","Puede omitirse según el contexto","Indica siempre un lugar"],"answer":"B","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-perspective","stage":"bachillerato","subject":"Dibujo Técnico","title":"Perspectiva cónica","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Perspectiva cónica","perspectiva conica","puntos de fuga"],"explanation":"La perspectiva cónica representa el espacio mediante proyecciones desde un punto de vista. Las rectas paralelas con una dirección que no sea paralela al plano del cuadro pueden converger en un punto de fuga. El horizonte se relaciona con la altura visual del observador.","simpler":"Las líneas que se alejan pueden parecer acercarse entre sí en el dibujo, aunque en el espacio sean paralelas.","example":"Los bordes paralelos de una carretera recta pueden dirigirse hacia un mismo punto de fuga en una representación adecuada.","why":"Cada dirección espacial puede tener su propio punto de fuga; algunas direcciones permanecen paralelas en la representación.","misconception":"Perspectiva cónica y dibujo a escala ortogonal no se interpretan igual.","hints":["Agrupa las rectas según su dirección espacial.","Las líneas que se alejan pueden parecer acercarse entre sí en el dibujo, aunque en el espacio sean paralelas.","Los bordes paralelos de una carretera recta pueden dirigirse hacia un mismo punto de fuga en una representación adecuada."],"quiz":[{"id":"b-perspective:q0","question":"Un punto de fuga representa la convergencia aparente de…","options":["Ciertas rectas paralelas","Todas las curvas","Solo círculos"],"answer":"A","hint":"Agrupa las rectas según su dirección espacial.","level":1},{"id":"b-perspective:q1","question":"El horizonte se relaciona con…","options":["El color del papel","El tamaño del lápiz","La altura visual del observador"],"answer":"C","hint":"Agrupa las rectas según su dirección espacial.","level":2},{"id":"b-perspective:q2","question":"¿Todas las paralelas del espacio comparten un único punto de fuga?","options":["Sí","No: depende de su dirección","Solo si son cortas"],"answer":"B","hint":"Agrupa las rectas según su dirección espacial.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."}]};
